    (target_deck_id, 'midnight', 'midnight', '''mɪdnaɪt', 'n. 午夜；子夜', 'You can’t phone her now – it’s gone midnight (= after midnight ) !', '你现在不能打电话给她，都过午夜了！', 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_1']::text[], 1176, '{"originalId":"PEPGaoZhong_1_176"}'::jsonb),
    (target_deck_id, 'at midnight', 'at midnight', NULL, '在午夜', 'She stole out of the house at midnight.', '她在半夜悄悄离开了家。', NULL, ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_1']::text[], 1177, '{"originalId":"PEPGaoZhong_1_177"}'::jsonb),
