    (target_deck_id, 'earthquake', 'earthquake', '''ɝθ''kwek', 'n. 地震', 'An earthquake measuring 6.1 on the Richter scale struck southern California on June 28.', '6月28日加州南部地区发生了里氏6.1级地震。', 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_1']::text[], 1184, '{"originalId":"PEPGaoZhong_1_184"}'::jsonb),
    (target_deck_id, 'quake', 'quake', 'kwek', 'n. 地震', 'The quake destroyed mud buildings in many remote villages.', '地震摧毁了许多偏远村庄的泥土房屋。', 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_1']::text[], 1185, '{"originalId":"PEPGaoZhong_1_185"}'::jsonb),
