    (target_deck_id, 'educate', 'educate', '''ɛdʒuket', 'vt. 教育；训练', 'The Ormerod School educates handicapped children.', '奥默罗德学校的教育对象为残疾儿童。', 'vt', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_1']::text[], 1294, '{"originalId":"PEPGaoZhong_1_294"}'::jsonb),
    (target_deck_id, 'educated', 'educated', '''ɛdʒə''ketɪd', 'adj. 有教养的；受过教育的', 'a highly educated woman', '很有修养的女子', 'adj', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_1']::text[], 1295, '{"originalId":"PEPGaoZhong_1_295"}'::jsonb),
    (target_deck_id, 'come to power', 'come to power', NULL, '当权；上台', 'On the other hand, a dismal leader could come to power in China and cause considerable damage to the economy.', '而另一方面，假如一个昏庸的领导人上台执政，就会给贵国经济带来严重损害。', NULL, ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_1']::text[], 1296, '{"originalId":"PEPGaoZhong_1_296"}'::jsonb),
    (target_deck_id, 'beg', 'beg', 'bɛɡ', 'v. 请求；乞求', 'She begged and pleaded with them until they finally agreed.', '她一再恳求，后来他们终于同意了。', 'v', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_1']::text[], 1297, '{"originalId":"PEPGaoZhong_1_297"}'::jsonb),
