    (target_deck_id, 'terror', 'terror', '''tɛrɚ', 'n. 恐怖；恐怖时期；恐怖活动', 'There was a look of sheer terror (= complete terror ) on his face.', '他脸上的表情异常惊恐。', 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_1']::text[], 1299, '{"originalId":"PEPGaoZhong_1_299"}'::jsonb),
