    (target_deck_id, 'sentence', 'sentence', '''sɛntəns', 'v. 判决；宣判', 'The judge has passed a sentence on the prisoner.', '法官已对犯人做出判决。', 'v', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_1']::text[], 1304, '{"originalId":"PEPGaoZhong_1_304"}'::jsonb),
    (target_deck_id, 'be sentenced to', 'be sentenced to', NULL, '被判处……（徒刑）', 'In Kenya, which is considered one of the more Westernized nations in Africa, gay people can be sentenced to years in prison.', '肯尼亚被认为是在非洲西化得较多的一个国家，那里的同性恋依然会被判处数年的监禁。', NULL, ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_1']::text[], 1305, '{"originalId":"PEPGaoZhong_1_305"}'::jsonb),
    (target_deck_id, 'anti-', 'anti-', '''æntaɪ', '[前缀]反；抗；阻', '...antiaircraft guns.', '...防空炮。', NULL, ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_1']::text[], 1306, '{"originalId":"PEPGaoZhong_1_306"}'::jsonb),
    (target_deck_id, 'anti-black', 'anti-black', ',ænti''blæk', 'adj. 反黑人的', 'Later, believing all mankind to be equal, he devoted himself to stopping the unfair anti-black laws.', '后来，因为相信所有人类都是生来平等，他全身心投入到废除不平等的反黑人法律工作中。', 'adj', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_1']::text[], 1307, '{"originalId":"PEPGaoZhong_1_307"}'::jsonb),
    (target_deck_id, 'Cape Town', 'cape town', NULL, '开普敦（南非立法首都）', 'I travelled from Cairo to Cape Town in 2002.', '2002年，我从开罗一路旅行到了开普敦。', NULL, ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_1']::text[], 1308, '{"originalId":"PEPGaoZhong_1_308"}'::jsonb),
