    (target_deck_id, 'decorate', 'decorate', '''dɛkəret', 'v. 装修；装饰', 'The bathroom is decorated in green and yellow.', '浴室里是用绿色和黄色装潢的。', 'v', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_2']::text[], 2022, '{"originalId":"PEPGaoZhong_2_22"}'::jsonb),
