    (target_deck_id, 'artist', 'artist', '''ɑrtɪst', 'n. 艺术家', 'an exhibition of paintings by local artists', '当地画家的画展', 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_2']::text[], 2024, '{"originalId":"PEPGaoZhong_2_24"}'::jsonb),
    (target_deck_id, 'belong', 'belong', 'bɪ''lɔŋ', 'v. 属于；为……的一员', 'The house had belonged to her family for three or four generations.', '这座房子属于她家已有三四代了。', 'v', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_2']::text[], 2025, '{"originalId":"PEPGaoZhong_2_25"}'::jsonb),
    (target_deck_id, 'belong to', 'belong to', NULL, '属于', 'They belong to someone.', '他们肯定属于某人。', NULL, ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_2']::text[], 2026, '{"originalId":"PEPGaoZhong_2_26"}'::jsonb),
    (target_deck_id, 'Peter the Great', 'peter the great', NULL, '彼得大帝（俄国皇帝）', 'But she knew that was only because, like Peter the Great in a shipwright''s yard, he was studying what he wanted to know.', '但是苔丝知道，那只是因为他要学习他想学习的东西，就像彼得大帝到造船厂里去学习一样。', NULL, ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_2']::text[], 2027, '{"originalId":"PEPGaoZhong_2_27"}'::jsonb),
    (target_deck_id, 'in return', 'in return', NULL, '作为报答；回报', '"Then can I have one answer in return?" he demanded.', '“那么，作为回报我要索取一个回答咯？” 他要求道。', NULL, ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_2']::text[], 2028, '{"originalId":"PEPGaoZhong_2_28"}'::jsonb),
    (target_deck_id, 'Czar', 'czar', 'zɑ:', 'n. 沙皇', NULL, NULL, 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_2']::text[], 2029, '{"originalId":"PEPGaoZhong_2_29"}'::jsonb),
    (target_deck_id, 'troop', 'troop', 'trʊp', 'n. 军队；群；组', 'Both countries agreed to withdraw their troops .', '两国都同意撤军。', 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_2', 'PEPGaoZhong_10']::text[], 2030, '{"originalId":"PEPGaoZhong_2_30"}'::jsonb),
    (target_deck_id, 'St Petersburg', 'st petersburg', NULL, 'n. 圣彼得堡（俄罗斯城市）', 'Imagine what it must have been like being a resident of St Petersburg in 1917, in the months before Lenin and the Bolsheviks finally seized power.', '想象一下，在1917年圣彼得堡，在列宁和布尔什维克最后夺取政权的几个月前，居民应该是怎么样的。', 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_2']::text[], 2031, '{"originalId":"PEPGaoZhong_2_31"}'::jsonb),
    (target_deck_id, 'reception', 'reception', 'rɪ''sɛpʃən', 'n. 接待；招待会；接收', 'She was unsure of her reception after everything that had happened.', '发生了这些事后，她对自己是否还受欢迎没把握。', 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_2']::text[], 2032, '{"originalId":"PEPGaoZhong_2_32"}'::jsonb),
    (target_deck_id, 'CatherineⅡ', 'catherineⅱ', '''kæθərin', '叶卡捷琳娜二世（俄国女皇）', NULL, NULL, NULL, ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_2']::text[], 2033, '{"originalId":"PEPGaoZhong_2_33"}'::jsonb),
    (target_deck_id, 'at war', 'at war', NULL, '处于交战状态', 'Still, we are a nation at war.', '但是，我们国家仍处在战争中。', NULL, ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_2']::text[], 2034, '{"originalId":"PEPGaoZhong_2_34"}'::jsonb),
    (target_deck_id, 'remove', 'remove', 'rɪ''muv', 'v. 移动；搬开', 'Remove the old wallpaper and fill any holes in the walls.', '撕下旧墙纸，把墙上的洞都填平。', 'v', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_2']::text[], 2035, '{"originalId":"PEPGaoZhong_2_35"}'::jsonb),
    (target_deck_id, 'less than', 'less than', NULL, '少于', 'Spend less than you earn, go without until you have the money.', '一定要比自己挣的花的少，如果没有那么多钱，就不要行动。', NULL, ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_2']::text[], 2036, '{"originalId":"PEPGaoZhong_2_36"}'::jsonb),
    (target_deck_id, 'wooden', 'wooden', '''wʊdn', 'adj. 木制的', 'a wooden bench', '木制长椅', 'adj', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_2']::text[], 2037, '{"originalId":"PEPGaoZhong_2_37"}'::jsonb),
    (target_deck_id, 'doubt', 'doubt', 'daʊt', 'n. 怀疑；疑惑
