    (target_deck_id, 'produce', 'produce', 'prəˈdus;(for n.)ˈprɒdus; prɑdus', 'n. 产品；（尤指）农产品', 'We manage to get most of our produce in farmers'' markets.', '我们设法在农贸市场弄到大部分我们需要的农产品。', 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_3']::text[], 3035, '{"originalId":"PEPGaoZhong_3_35"}'::jsonb),
    (target_deck_id, 'rooster', 'rooster', '''rustɚ', 'n. 雄禽；公鸡', 'The cock (or rooster) bristled his crest.', '公鸡竖起了鸡冠。', 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_3']::text[], 3036, '{"originalId":"PEPGaoZhong_3_36"}'::jsonb),
    (target_deck_id, 'admire', 'admire', 'ədˈmaɪr', 'v. 赞美；钦佩；羡慕', 'I really admire the way she brings up those kids all on her own.', '我十分佩服她独力把那些孩子抚养大。', 'v', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_3']::text[], 3037, '{"originalId":"PEPGaoZhong_3_37"}'::jsonb),
    (target_deck_id, 'energetic', 'energetic', ',ɛnɚ''dʒɛtɪk', 'adj. 充满活力的；精力充沛的；积极的', 'an energetic man', '精力旺盛的男子', 'adj', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_3']::text[], 3038, '{"originalId":"PEPGaoZhong_3_38"}'::jsonb),
