    (target_deck_id, 'carnival', 'carnival', '''kɑrnɪvl', 'n. 狂欢节；（四旬斋前的）饮宴狂欢；嘉年华（会）', 'preparations for this year’s carnival', '今年狂欢节的准备工作', 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_3']::text[], 3040, '{"originalId":"PEPGaoZhong_3_40"}'::jsonb),
