    (target_deck_id, 'Easter', 'easter', 'istəʳ', 'n. (耶稣)复活节', 'on Easter Sunday', '在复活节星期日', 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_3']::text[], 3042, '{"originalId":"PEPGaoZhong_3_42"}'::jsonb),
