    (target_deck_id, 'as though', 'as though', NULL, '好像', 'The boy gabbled off the poem as though he neither understood nor enjoyed it.', '这个小男孩急促而漫不经心地朗诵着诗，他好像既不懂这首诗又不喜欢这首诗。', NULL, ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_3']::text[], 3050, '{"originalId":"PEPGaoZhong_3_50"}'::jsonb),
    (target_deck_id, 'have fun with', 'have fun with', NULL, '玩得开心', 'Now you can find your passion for exercise and have fun with your kids at the same time.', '现在你可以在拥有锻炼的热情的同时和孩子们享受快乐时光。', NULL, ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_3']::text[], 3051, '{"originalId":"PEPGaoZhong_3_51"}'::jsonb),
    (target_deck_id, 'custom', 'custom', '''kʌstəm', '习惯；风俗', 'That custom has fallen off.', '那个风俗已经废弃了。', NULL, ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_3']::text[], 3052, '{"originalId":"PEPGaoZhong_3_52"}'::jsonb),
    (target_deck_id, 'worldwide', 'worldwide', '''wɝldwaɪd', 'adj. 遍及全世界的；世界性的', 'We have offices in over 56 countries worldwide.', '我们在全世界超过56个国家设有办事处。', 'adj', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_3']::text[], 3053, '{"originalId":"PEPGaoZhong_3_53"}'::jsonb),
    (target_deck_id, 'rosebud', 'rosebud', '''rozbʌd', 'n. 玫瑰花蕾', 'When we think we see something, say like a small red rosebud, we think our friend will see the same rosebud, same shape, same size.', '当我们觉得我们看到了什么东西，比如说一个红色的小玫瑰花蕾，我们会觉得我们的朋友们看到的也是同样的玫瑰花蕾，同样的颜色，同样的大小。', 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_3']::text[], 3054, '{"originalId":"PEPGaoZhong_3_54"}'::jsonb),
    (target_deck_id, 'fool', 'fool', 'ful', 'n. 愚人；白痴；受骗者
v. 干傻事；开玩笑
adj. 傻的', 'I suddenly realised that I was being made a fool of.', '我突然明白过来，我被人耍了。', 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_3']::text[], 3055, '{"originalId":"PEPGaoZhong_3_55"}'::jsonb),
    (target_deck_id, 'necessity', 'necessity', 'nə''sɛsəti', 'n. 必要性；需要', 'I’m afraid it’s become a matter of economic necessity.', '恐怕这已成了一个经济需求的问题。', 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_3']::text[], 3056, '{"originalId":"PEPGaoZhong_3_56"}'::jsonb),
    (target_deck_id, 'permission', 'permission', 'pɚ''mɪʃən', 'n. 许可；允许', 'He asked permission to leave the room.', '他请求离开房间的许可。', 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_3']::text[], 3057, '{"originalId":"PEPGaoZhong_3_57"}'::jsonb),
    (target_deck_id, 'prediction', 'prediction', 'prɪ''dɪkʃən', 'n. 预言；预报；预告', 'The data can be used to make useful economic predictions .', '这些数据可用于进行有用的经济预测。', 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_3']::text[], 3058, '{"originalId":"PEPGaoZhong_3_58"}'::jsonb),
    (target_deck_id, 'fashion', 'fashion', '''fæʃən', 'n. 时尚；样子；方式', 'His ideas are coming back into fashion (= they are becoming popular again ) .', '他的观点又流行起来。', 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_3', 'PEPGaoZhong_9']::text[], 3059, '{"originalId":"PEPGaoZhong_3_59"}'::jsonb),
    (target_deck_id, 'Trinidad', 'trinidad', '''trinidæd; ,tri:ni''ðɑ:ð', 'n. 特立尼达岛', 'In Trinidad, I proposed an Energy and Climate Partnership for the Americas.', '在特立尼达，我提出了美洲国家能源和气候合作计划。', 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_3']::text[], 3060, '{"originalId":"PEPGaoZhong_3_60"}'::jsonb),
    (target_deck_id, 'Carla', 'carla', NULL, 'n. 卡拉（女名）', 'He sees that cancer is a world unto itself; that Carla is now part of this world; and that he is part of it, too.', '他认识到癌症就是一个自我施加的世界；卡拉现在就是这个世界的一部分了；而他自己也是这个世界的一部分。', 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_3']::text[], 3061, '{"originalId":"PEPGaoZhong_3_61"}'::jsonb),
    (target_deck_id, 'Hari', 'hari', NULL, 'n. 哈利（男名）', 'Johann Hari is a writer for the Independent newspaper.', '约翰 • 哈里是《独立报》作家。', 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_3']::text[], 3062, '{"originalId":"PEPGaoZhong_3_62"}'::jsonb),
    (target_deck_id, 'parking', 'parking', '''pɑrkɪŋ', 'n. （汽车等）停放', 'No Parking (= used on signs )', '禁止停车', 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_3']::text[], 3063, '{"originalId":"PEPGaoZhong_3_63"}'::jsonb),
    (target_deck_id, 'parking lot', 'parking lot', NULL, '停车场', 'If you drive to work, park at the far end of the parking lot.', '如果你开车上班，那么就将汽车泊在停车场的最远端。', NULL, ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_3']::text[], 3064, '{"originalId":"PEPGaoZhong_3_64"}'::jsonb),
    (target_deck_id, 'Valentine’s Day', 'valentine’s day', NULL, 'n. 圣瓦伦廷节；情人节', NULL, NULL, 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_3']::text[], 3065, '{"originalId":"PEPGaoZhong_3_65"}'::jsonb),
    (target_deck_id, 'turn up', 'turn up', NULL, '出现；到场', 'They finally turned up at nearly midnight.', '他们终于在近午夜时出现了。', NULL, ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_3']::text[], 3066, '{"originalId":"PEPGaoZhong_3_66"}'::jsonb),
    (target_deck_id, 'keep one’s word', 'keep one’s word', NULL, '守信用；履行诺言', '“He’s saying one thing and he’s doing the other,” McCain declared, urging Obama to “keep your word to the American people.”', '麦凯恩说："他说的是一回事，做的是另一回事。" 他敦促奥巴马："遵守你对美国人民的承诺"。', NULL, ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_3']::text[], 3067, '{"originalId":"PEPGaoZhong_3_67"}'::jsonb),
    (target_deck_id, 'hold one’s breath', 'hold one’s breath', NULL, '屏息；屏气', 'It'' s possible to hold one '' s breath for three minutes, with practice.', '经过练习，屏住呼吸三分钟是可能的。', NULL, ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_3']::text[], 3068, '{"originalId":"PEPGaoZhong_3_68"}'::jsonb),
    (target_deck_id, 'apologize', 'apologize', 'ə''pɑlədʒaɪz', 'v. 道歉；辩白', 'I’m so sorry, I do apologize.', '非常对不起，我真心道歉。', 'v', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_3']::text[], 3069, '{"originalId":"PEPGaoZhong_3_69"}'::jsonb),
    (target_deck_id, 'drown', 'drown', 'draʊn', 'v. 淹没；溺死；淹死', 'Many people drowned when the boat overturned.', '船翻后许多人淹死了。', 'v', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_3']::text[], 3070, '{"originalId":"PEPGaoZhong_3_70"}'::jsonb)
