    (target_deck_id, 'sadness', 'sadness', '''sædnəs', 'n. 悲哀，悲伤', 'There was a touch of sadness in his voice (= he sounded a little sad ) .', '他的声音里含着一丝悲伤。', 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_3']::text[], 3071, '{"originalId":"PEPGaoZhong_3_71"}'::jsonb),
    (target_deck_id, 'obvious', 'obvious', '''ɑbvɪəs', 'adj. 明显的；显而易见的', 'The obvious way of reducing pollution is to use cars less.', '减少污染显而易见的办法就是少用汽车。', 'adj', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_3']::text[], 3072, '{"originalId":"PEPGaoZhong_3_72"}'::jsonb),
    (target_deck_id, 'wipe', 'wipe', 'waɪp', 'v. 擦；揩；擦去', 'I''ll just wipe the table.', '我只擦擦桌子。', 'v', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_3']::text[], 3073, '{"originalId":"PEPGaoZhong_3_73"}'::jsonb),
    (target_deck_id, 'weave', 'weave', 'wiv', 'v. (过去式 wove, 过去分词 woven)（使）迂回', 'cyclists weaving in and out of the traffic', '在车流中穿进穿出的骑车人', 'v', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_3']::text[], 3074, '{"originalId":"PEPGaoZhong_3_74"}'::jsonb),
    (target_deck_id, 'herd', 'herd', 'hɝd', 'n. 牧群；兽群', 'Chobe is also renowned for its large herds of elephant and buffalo.', '乔贝还以其大群的大象和水牛而闻名。', 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_3']::text[], 3075, '{"originalId":"PEPGaoZhong_3_75"}'::jsonb),
    (target_deck_id, 'the Milky Way', 'the milky way', NULL, '银河', 'More of our children should be able to look up at night and see that the Milky Way is not just a candy bar .', '我们应该有更多的孩子能够仰望夜空，眼中所看到的银河不应仅仅只是（模糊的）“一条糖块”而已。', NULL, ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_3']::text[], 3076, '{"originalId":"PEPGaoZhong_3_76"}'::jsonb),
    (target_deck_id, 'magpie', 'magpie', '''mæɡpai', 'n. 喜鹊', NULL, NULL, 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_3']::text[], 3077, '{"originalId":"PEPGaoZhong_3_77"}'::jsonb),
