    (target_deck_id, 'phenomenon', 'phenomenon', 'fə''nɑmɪnən', 'n. 现象', 'Homelessness is not a new phenomenon .', '无家可归已不是什么新现象。', 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_6']::text[], 6246, '{"originalId":"PEPGaoZhong_6_246"}'::jsonb),
    (target_deck_id, 'subscribe', 'subscribe', 'səb''skraɪb', 'v. (to)订阅，订购', 'You can subscribe to the magazine for as little as 32 a year.', '一年只需 32 美元就可以订阅这份杂志。', 'v', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_6', 'PEPGaoZhong_11']::text[], 6247, '{"originalId":"PEPGaoZhong_6_247"}'::jsonb),
    (target_deck_id, 'subscribe to', 'subscribe to', NULL, '同意；赞成；订购', 'I have never subscribed to the view that schooldays are the happiest days of your life.', '我从未赞同过这样的看法，以为学生时代是一生中最快乐的日子。', NULL, ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_6']::text[], 6248, '{"originalId":"PEPGaoZhong_6_248"}'::jsonb),
    (target_deck_id, 'fossil', 'fossil', '''fɑsl', 'n. 化石', 'fossils of early reptiles', '早期爬行动物的化石', 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_6']::text[], 6249, '{"originalId":"PEPGaoZhong_6_249"}'::jsonb),
    (target_deck_id, 'fuel', 'fuel', '''fjuəl', 'n. 燃料', 'Coal is one of the cheapest fuels.', '煤是最廉价的燃料之一。', 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_6']::text[], 6250, '{"originalId":"PEPGaoZhong_6_250"}'::jsonb),
    (target_deck_id, 'byproduct', 'byproduct', '''baɪ,prɑdəkt', 'n. 副产品', 'The raw material for the tyre is a byproduct of oil refining.', '这种轮胎的原料是汽油提炼的副产品。', 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_6']::text[], 6251, '{"originalId":"PEPGaoZhong_6_251"}'::jsonb),
    (target_deck_id, 'Janice', 'janice', '''dʒænis', '贾尼丝（女名）', 'Janice: It''s been three years!', '贾尼斯：三年了！', NULL, ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_6']::text[], 6252, '{"originalId":"PEPGaoZhong_6_252"}'::jsonb),
    (target_deck_id, 'Foster', 'foster', '''fɔstɚ', '福斯特（姓或男名）', NULL, NULL, NULL, ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_6']::text[], 6253, '{"originalId":"PEPGaoZhong_6_253"}'::jsonb),
    (target_deck_id, 'methane', 'methane', '''mɛθen', 'n. 甲烷；沼气', 'Methane is one of the principal gases contributing to the greenhouse effect.', '甲烷是造成温室效应的主要气体之一。', 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_6']::text[], 6254, '{"originalId":"PEPGaoZhong_6_254"}'::jsonb),
    (target_deck_id, 'Celsius', 'celsius', '''sɛlsɪəs', 'adj. (温度)摄氏的', 'Highest temperatures 11° Celsius, that''s 52° Fahrenheit.', '最高温度11摄氏度，即52华氏度。', 'adj', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_6']::text[], 6255, '{"originalId":"PEPGaoZhong_6_255"}'::jsonb),
    (target_deck_id, 'quantity', 'quantity', '''kwɑntəti', 'n. 量；数量', 'Your work has improved in quantity and quality this term.', '这学期你的作业在完成数量和质量上都有提高。', 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_6']::text[], 6256, '{"originalId":"PEPGaoZhong_6_256"}'::jsonb),
