    (target_deck_id, 'Mount Etna', 'mount etna', NULL, '埃特纳火山（意大利西西里岛东北部）', 'Mount Etna holds a place in Roman mythology as the furnace of the god of fire and blacksmithing.', '埃特纳火山在罗马神话中占有一席之地。 它是火与锻冶之神的熔炉。', NULL, ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_6']::text[], 6351, '{"originalId":"PEPGaoZhong_6_351"}'::jsonb),
    (target_deck_id, 'Sicily', 'sicily', '''sisili', '西西里岛（意大利南部）', 'A group of wealthy friends are cruising the sea near Sicily on a yacht.', '一群有钱人开着游艇在西西里岛附近的海上游弋。', NULL, ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_6']::text[], 6352, '{"originalId":"PEPGaoZhong_6_352"}'::jsonb),
