    (target_deck_id, 'never mind', 'never mind', NULL, '不必担心', '‘We haven’t done very well, have we?’ ‘Never mind. At least we tried.’', '“我们做得不太好，是不是？”“没关系，至少我们尝试过了。”', NULL, ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_7']::text[], 7049, '{"originalId":"PEPGaoZhong_7_49"}'::jsonb),
