    (target_deck_id, 'Mount Kilimanjaro', 'mount kilimanjaro', NULL, 'n. 乞力马扎罗山（位于坦桑尼亚；非洲最高山）', 'Couple Mikey and Tanya Carr-Hartley have a 56.56-hectare estate in the shadow of Mount Kilimanjaro.', '麦基和坦雅夫妇在乞力马扎罗山脚下拥有一个占地56.56公顷的庄园。', 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_7']::text[], 7057, '{"originalId":"PEPGaoZhong_7_57"}'::jsonb),
    (target_deck_id, 'companion', 'companion', 'kəm''pænɪən', 'n. 同伴；伙伴', 'For ten years he had been her constant companion .', '十年来他一直陪伴她左右。', 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_7']::text[], 7058, '{"originalId":"PEPGaoZhong_7_58"}'::jsonb),
