    (target_deck_id, 'oilfield', 'oilfield', '''ɔɪlfild', 'n. 油田', 'Systems engineering has been widely applied in the oilfield exploitation and construction.', '近年来，系统工程学在油田开发建设中应用广泛。', 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_7']::text[], 7359, '{"originalId":"PEPGaoZhong_7_359"}'::jsonb),
    (target_deck_id, 'Jamie', 'jamie', NULL, 'n. 杰米（男名）', '"Contractors are using fine print to deny women like Jamie Leigh Jones their day in court, " he said in a Senate debate.', '“承包商钻了法律的空子，拒绝类似杰米·雷·琼斯遭遇的妇女走向法庭。” 他在参议院辩论上说。', 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_7']::text[], 7360, '{"originalId":"PEPGaoZhong_7_360"}'::jsonb),
