  ) VALUES
    (target_deck_id, 'Lima', 'lima', '''limə', 'n. 利马（秘鲁首都）', 'In places like Sao Paolo, Mexico City and Lima, the best restaurants are as good as anywhere in the world.', '在圣保罗、墨西哥城和利马，那里最好的餐厅拿到世界上任何地方都是最好的。', 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_7']::text[], 7362, '{"originalId":"PEPGaoZhong_7_362"}'::jsonb),
    (target_deck_id, 'Cuzco', 'cuzco', '''ku:skəu', 'n. 库斯科（秘鲁南部城市）', 'In total, slides have killed five people in the Cuzco region.', '在库斯科地区泥石流总共已使5人丧生。', 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_7']::text[], 7363, '{"originalId":"PEPGaoZhong_7_363"}'::jsonb),
    (target_deck_id, 'the Andes', 'the andes', NULL, '安第斯山脉', 'Meanwhile, in Bolivia, halfway around the world and smack in the middle of the Andes, the controversy is causing chuckles.', '与此同时，在玻利维亚，在半个世界以及中东的安第斯山脉，这个争议引发了轻笑。', NULL, ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_7']::text[], 7364, '{"originalId":"PEPGaoZhong_7_364"}'::jsonb),
    (target_deck_id, 'Peru', 'peru', 'pə''rʊ', 'n. 秘鲁（南美国家）', 'It sounds as though you enjoyed Peru.', '这听起来好像你喜欢秘鲁。', 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_7']::text[], 7365, '{"originalId":"PEPGaoZhong_7_365"}'::jsonb),
