    (target_deck_id, 'agent', 'agent', '''edʒənt', 'n. 代理人；经纪人', 'Our agent in Rio deals with all our Brazilian business.', '我们在里约热内卢的业务代表处理我们在巴西的全部业务。', 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_7']::text[], 7367, '{"originalId":"PEPGaoZhong_7_367"}'::jsonb),
    (target_deck_id, 'travel agent', 'travel agent', NULL, '旅行代办人；旅行代理人', 'Next, I called a travel agent whose telephone number I found in a newspaper.', '接下来，我在报纸上查到一家旅行社代理人的电话号码，给他打了电话。', NULL, ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_7']::text[], 7368, '{"originalId":"PEPGaoZhong_7_368"}'::jsonb),
    (target_deck_id, 'geographical', 'geographical', 'dʒɪə''græfɪkl', 'adj. 地理（学）的', 'their geographical proximity to Japan (= nearness to Japan )', '它们和日本相邻的地理位置', 'adj', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_7']::text[], 7369, '{"originalId":"PEPGaoZhong_7_369"}'::jsonb),
    (target_deck_id, 'parallel', 'parallel', '''pærəlɛl', 'adj. 平行的；相同的；类似的', 'Lines AB and CD are parallel. AB', '线与CD线平行。', 'adj', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_7']::text[], 7370, '{"originalId":"PEPGaoZhong_7_370"}'::jsonb),
