    (target_deck_id, 'Machu Picchu', 'machu picchu', NULL, '马丘比丘（秘鲁）', 'The next day the Espinar water strike spreads to communities near Machu Picchu.', '第二天，埃斯皮纳水罢工扩大到马丘比丘附近的社区。', NULL, ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_7']::text[], 7377, '{"originalId":"PEPGaoZhong_7_377"}'::jsonb),
    (target_deck_id, 'inn', 'inn', 'ɪn', 'n. 客栈', 'We’re staying at the Holiday Inn.', '我们住在假日酒店。', 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_7']::text[], 7378, '{"originalId":"PEPGaoZhong_7_378"}'::jsonb),
    (target_deck_id, 'out of the question', 'out of the question', NULL, '不可能的；不值得讨论的', 'He could draw men round him and keep them bound to him; while his powerful attraction was there, disruption was out of the question.', '他能够把人们吸引到他的周围而且保持他们的忠心；而他的强大吸引力所在之处，就不可能有分裂。', NULL, ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_7']::text[], 7379, '{"originalId":"PEPGaoZhong_7_379"}'::jsonb),
