    (target_deck_id, 'the Arctic', 'the arctic', NULL, '北极', '"We only have 50 years of observations of the Arctic, " Miller said, referring primarily to satellite sea ice observations.', '米勒说：“我们只进行了50年的北极观测，”，他主要指的是卫星进行的海冰观测。', NULL, ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_8']::text[], 8011, '{"originalId":"PEPGaoZhong_8_11"}'::jsonb),
