    (target_deck_id, 'a good many', 'a good many', NULL, '许多；很多', 'There is an active Society which brings to book a good many parents who starve and torture and overwork their children, and intimidates a good many more.', '一个很积极的社会记录了许多父母是怎样让自己的孩子忍饥挨饿，折磨他们，让他们过度工作，对他们愈加 恐吓的。', NULL, ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_8']::text[], 8080, '{"originalId":"PEPGaoZhong_8_80"}'::jsonb),
    (target_deck_id, 'apply for', 'apply for', NULL, '申请；请示得到', 'We need to apply for planning permission to build a garage.', '我们建车库需要申请规划许可。', NULL, ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_8']::text[], 8081, '{"originalId":"PEPGaoZhong_8_81"}'::jsonb),
