    (target_deck_id, 'caption', 'caption', '''kæpʃən', 'n. （图片上的）说明文字；（电视、电影）字幕；（杂志等文章的）标题；', 'The local paper featured me standing on a stepladder with a caption, "Wendy climbs the ladder to success."', '当地的报纸刊登了一幅我站在活梯上的特写，下面写着：“温迪登上了成功之梯。”', 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_8', 'PEPGaoZhong_10']::text[], 8261, '{"originalId":"PEPGaoZhong_8_261"}'::jsonb),
    (target_deck_id, 'plot', 'plot', 'plɑt', 'n. 阴谋；情节', 'The court heard how she and her lover hatched a plot (= planned a plot ) to kill her husband.', '法庭听取了她和情人密谋杀害她丈夫的案情。', 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_8']::text[], 8262, '{"originalId":"PEPGaoZhong_8_262"}'::jsonb),
    (target_deck_id, 'professor', 'professor', 'prə''fɛsɚ', 'n. 教授', 'Professor Barclay', '巴克利教授', 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_8']::text[], 8263, '{"originalId":"PEPGaoZhong_8_263"}'::jsonb),
    (target_deck_id, 'Higgins', 'higgins', NULL, '希金斯 （姓）', 'Hey, this may be a way of getting rid of Dean Higgins.', '嘿，这可能是一个摆脱希金斯院长的一个方法。', NULL, ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_8']::text[], 8264, '{"originalId":"PEPGaoZhong_8_264"}'::jsonb),
    (target_deck_id, 'phonetics', 'phonetics', 'fə''nɛtɪks', 'n. 语音学', 'Forensics includes many fields of science, including anthropology, biology, chemistry, engineering, genetics, medicine, pathology, phonetics, psychiatry, and toxicology.', '法医物证学涉及到多个科学领域，包括人类学、工程学、医药学、病理学、语音学、精神病学和毒理学。', 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_8']::text[], 8265, '{"originalId":"PEPGaoZhong_8_265"}'::jsonb),
    (target_deck_id, 'colonel', 'colonel', '''kɝnl', 'n. （陆军）上校', 'What if they go on to behave as murderously as the colonel and his paid killers?', '如果他们像他们的是上校和他的杀手们一样继续表现为杀气腾腾的又该怎么办？', 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_8']::text[], 8266, '{"originalId":"PEPGaoZhong_8_266"}'::jsonb),
    (target_deck_id, 'Pickering', 'pickering', '''pikəriŋ', '皮克林（姓）', '“We are now at the beginning of the beginning” of a new relationship, Pickering said.', '皮克林说，我们现在处于两国新关系的“开端的开端”。', NULL, ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_8']::text[], 8267, '{"originalId":"PEPGaoZhong_8_267"}'::jsonb),
    (target_deck_id, 'fateful', 'fateful', '''fetfl', 'adj. 重要的；决定性的；命中注定的', 'It was a fateful decision, one which was to break the Government.', '那是一项重大的决定，一个将使政府垮台的决定。', 'adj', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_8']::text[], 8268, '{"originalId":"PEPGaoZhong_8_268"}'::jsonb),
