    (target_deck_id, 'brilliant', 'brilliant', '''brɪljənt', 'adj. 才华横溢的；光辉灿烂的；杰出的', 'I think that’s a brilliant idea .', '我觉得那是个绝妙的主意。', 'adj', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_8']::text[], 8283, '{"originalId":"PEPGaoZhong_8_283"}'::jsonb),
