    (target_deck_id, 'extraordinary', 'extraordinary', 'ɪkˈstrɔrdənerɪ; ɪkˈstrɔrdnˌɛrɪ', 'adj. 不同寻常的；非凡的', 'It took an extraordinary amount of work.', '这费了相当多的功夫。', 'adj', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_8']::text[], 8288, '{"originalId":"PEPGaoZhong_8_288"}'::jsonb),
