    (target_deck_id, 'duchess', 'duchess', '''dʌtʃəs', 'n. 公爵夫人；女公爵', 'the Duchess of York', '约克公爵夫人', 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_8']::text[], 8293, '{"originalId":"PEPGaoZhong_8_293"}'::jsonb),
    (target_deck_id, 'ambassador', 'ambassador', 'æm''bæsədɚ', 'n. 大使；使节', '...the German ambassador to Poland.', '…德国驻波兰大使。', 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_8']::text[], 8294, '{"originalId":"PEPGaoZhong_8_294"}'::jsonb),
    (target_deck_id, 'acquaintance', 'acquaintance', 'ə''kwentəns', 'n. 熟人；相识；了解', 'She was a casual acquaintance of my family in Vienna.', '她是我们家在维也纳的一个交情不深的朋友。', 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_8']::text[], 8295, '{"originalId":"PEPGaoZhong_8_295"}'::jsonb),
    (target_deck_id, 'make one’s acquaintance', 'make one’s acquaintance', NULL, '结识；与……相见', 'I should be delighted to make Mrs McGough’s acquaintance.', '我很高兴能认识麦高夫太太。', NULL, ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_8']::text[], 8296, '{"originalId":"PEPGaoZhong_8_296"}'::jsonb),
    (target_deck_id, 'handful', 'handful', '''hænd,fʊl', 'n. 一把；几个人', 'The boy picked up a handful of stones and started throwing them at us.', '那男孩捡起一把石子，开始朝我们扔过来。', 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_8']::text[], 8297, '{"originalId":"PEPGaoZhong_8_297"}'::jsonb),
    (target_deck_id, 'amazement', 'amazement', 'ə''mezmənt', 'n. 惊讶；惊愕', 'I stared at her in amazement.', '我惊讶地盯着她。', 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_8']::text[], 8298, '{"originalId":"PEPGaoZhong_8_298"}'::jsonb),
    (target_deck_id, 'in amazement', 'in amazement', NULL, '震惊；惊讶', 'They reacted with sighs of disappointment and stared in amazement at Hanna, who had more or less won the exchange.', '他们都发出了失望的叹息，惊讶地盯着汉娜，她或多或少赢得了些理解。', NULL, ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_8']::text[], 8299, '{"originalId":"PEPGaoZhong_8_299"}'::jsonb),
    (target_deck_id, 'fortune', 'fortune', '''fɔrtʃən', 'n. 大笔的钱；机会；运气', 'He made a fortune selling property in Spain.', '他在西班牙卖房产，发了大财。', 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_8']::text[], 8300, '{"originalId":"PEPGaoZhong_8_300"}'::jsonb),
    (target_deck_id, 'authentic', 'authentic', 'ɔ''θɛntɪk', 'adj. 真实的；真正的；可信的； 可靠的', 'an authentic account', '真实可信的说法', 'adj', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_8']::text[], 8301, '{"originalId":"PEPGaoZhong_8_301"}'::jsonb),
    (target_deck_id, 'generally speaking', 'generally speaking', NULL, '一般来说', 'Sure, I saw him but, generally speaking, drunks falling over are not my problem. Next time I see one I will do the same.', '我答道：“当然，我看见了他，但是一般而言，醉汉摔倒并不关我的事，下次遇到同样的事情我还是会像今天这么做的。”', NULL, ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_8']::text[], 8302, '{"originalId":"PEPGaoZhong_8_302"}'::jsonb),
