    (target_deck_id, 'stocking', 'stocking', '''stɑkɪŋ', 'n. 长袜', '...a pair of nylon stockings.', '…一双尼龙长袜。', 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_8']::text[], 8310, '{"originalId":"PEPGaoZhong_8_310"}'::jsonb),
    (target_deck_id, 'believer', 'believer', 'bɪ''livɚ', 'n. 信徒；教徒', 'I made no secret of the fact that I was not a believer.', '我对自己不是一个宗教信徒的事实并不隐瞒。', 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_8']::text[], 8311, '{"originalId":"PEPGaoZhong_8_311"}'::jsonb),
