    (target_deck_id, 'vowel', 'vowel', '''vaʊəl', 'n. 元音；元音字母', 'Always end the name of your child with a vowel, so that when you yell the name will carry.', '一定让孩子的名字以元音结尾，这样当你喊叫时，这样的名字会助你一臂之力。', 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_8']::text[], 8315, '{"originalId":"PEPGaoZhong_8_315"}'::jsonb),
