    (target_deck_id, 'discourage', 'discourage', 'dɪs''kɝɪdʒ', 'v. 使……气馁', 'It may be difficult to do at first. Don''t let this discourage you.', '开始时做起来也许比较困难。不要让这个泄你的气。', 'v', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_10']::text[], 10060, '{"originalId":"PEPGaoZhong_10_60"}'::jsonb),
    (target_deck_id, 'give off', 'give off', NULL, '发出（蒸汽，光等）', '...natural gas, which gives off less carbon dioxide than coal.', '…天然气的二氧化碳排放量少于煤。', NULL, ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_10']::text[], 10064, '{"originalId":"PEPGaoZhong_10_64"}'::jsonb),
    (target_deck_id, 'Lionel Greenstreet', 'lionel greenstreet', NULL, '莱昂内尔.格林斯特里特', NULL, NULL, NULL, ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_10']::text[], 10065, '{"originalId":"PEPGaoZhong_10_65"}'::jsonb),
    (target_deck_id, 'liver', 'liver', '''lɪvɚ', 'n. 肝脏', 'Three weeks ago, it was discovered the cancer had spread to his liver.', '三周前，发现癌已扩散到了他的肝脏。', 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_10']::text[], 10067, '{"originalId":"PEPGaoZhong_10_67"}'::jsonb),
    (target_deck_id, 'chef', 'chef', 'ʃɛf', 'n. 厨师，主厨', 'a master chef', '手艺高超的厨师长', 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_10']::text[], 10068, '{"originalId":"PEPGaoZhong_10_68"}'::jsonb)
  ON CONFLICT (deck_id, normalized_word) DO NOTHING;

  INSERT INTO public.word_entries (
    deck_id, word, normalized_word, phonetic, meaning, example, example_translation, part_of_speech, tags, sort_index, metadata
  ) VALUES
    (target_deck_id, 'changeable', 'changeable', '''tʃendʒəbl', 'adj. 可改变的', 'changeable weather', '变化无常的天气', 'adj', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_10']::text[], 10069, '{"originalId":"PEPGaoZhong_10_69"}'::jsonb),
    (target_deck_id, 'sun-blindness', 'sun-blindness', NULL, 'n. 日盲症，（因阳光强烈导致的暂时）失明', NULL, NULL, 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_10']::text[], 10071, '{"originalId":"PEPGaoZhong_10_71"}'::jsonb),
    (target_deck_id, 'proverb', 'proverb', '''prɑvɝb', 'n. 谚语', 'An old Arab proverb says, "The enemy of my enemy is my friend."', '有一句古老的阿拉伯谚语说：“我敌人的敌人是我的朋友。”', 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_10']::text[], 10074, '{"originalId":"PEPGaoZhong_10_74"}'::jsonb),
    (target_deck_id, 'King Lear', 'king lear', NULL, '李尔王', 'Land rose from its womb, usurped its throne, and ever since the maddened old creature, with hoary crest of foam, wails and laments continually, like King Lear exposed to the fury of the elements.', '大地从它的腹中隆起，篡夺了它的王位。 从那以后，暴怒的老家伙就开始顶着灰白色的泡沫不断的哀号恸哭，一如暴风骤雨之中的李尔王。', NULL, ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_10']::text[], 10075, '{"originalId":"PEPGaoZhong_10_75"}'::jsonb),
    (target_deck_id, 'disrespectful', 'disrespectful', 'disri,spektful', 'adj. 失礼的，无礼的', '...accusations that he had been disrespectful to a police officer.', '...关于他曾对一名警官无礼的控告。', 'adj', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_10']::text[], 10077, '{"originalId":"PEPGaoZhong_10_77"}'::jsonb),
    (target_deck_id, 'disrespectfully', 'disrespectfully', NULL, 'adv. 失礼地，无理地', 'It jumped up and down disrespectfully, mocking the hunting soldiers. It threw a nut at them.', '它无礼地上窜下跳，戏弄士兵们，还朝他们扔果核。', 'adv', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_10']::text[], 10078, '{"originalId":"PEPGaoZhong_10_78"}'::jsonb),
    (target_deck_id, 'emperor', 'emperor', '''ɛmpərɚ', 'n. 皇帝，君主', 'They caballed against the emperor''s edict.', '他们密谋反对皇帝的谕旨。', 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_10']::text[], 10079, '{"originalId":"PEPGaoZhong_10_79"}'::jsonb),
    (target_deck_id, 'shorten', 'shorten', '''ʃɔrtn', 'v. 缩短，使变短', 'The days are shortening.', '白天变得越来越短了。', 'v', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_10']::text[], 10080, '{"originalId":"PEPGaoZhong_10_80"}'::jsonb),
    (target_deck_id, 'modernize', 'modernize', 'mɑdɚnˌaɪz', 'vt. 使现代化', 'They need more funds to modernize the country’s telephone system.', '他们需要更多的资金将本国的电话系统现代化。', 'vt', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_10']::text[], 10081, '{"originalId":"PEPGaoZhong_10_81"}'::jsonb),
    (target_deck_id, 'throne', 'throne', 'θron', 'n. 王座，王位', 'He is next in line to the throne (= will become king when the present ruler dies ) .', '他是第一王位继承人。', 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_10']::text[], 10082, '{"originalId":"PEPGaoZhong_10_82"}'::jsonb),
    (target_deck_id, 'Regan', 'regan', NULL, '里根', 'She also says that on one occasion, Regan hung up on her in the middle of a phone conversation.', '她还表示，有一次，在电话交谈中，里根挂了她的电话。', NULL, ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_10']::text[], 10083, '{"originalId":"PEPGaoZhong_10_83"}'::jsonb),
    (target_deck_id, 'Goneril', 'goneril', '''ɡɔnəril', '贡纳莉', 'This part is equal in value to what I give to Goneril.', '这部份和我给贡纳莉的那部份价值相等。', NULL, ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_10']::text[], 10084, '{"originalId":"PEPGaoZhong_10_84"}'::jsonb),
    (target_deck_id, 'Cordelia', 'cordelia', 'kɔ:''di:ljə', '科迪莉亚', 'Don''t grudge Anne Cordelia her fancies, Diana. I''m always sorry for children who don''t spend a few years in fairyland.', '不要对安妮.科迪莉亚的想象力不满，戴安娜，我总是为没有在童话世界中度过一段岁月的孩子感到遗憾。', NULL, ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_10']::text[], 10085, '{"originalId":"PEPGaoZhong_10_85"}'::jsonb),
    (target_deck_id, 'duke', 'duke', 'dʊk', 'n. 公爵', 'the Duke of Norfolk', '诺福克公爵', 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_10']::text[], 10086, '{"originalId":"PEPGaoZhong_10_86"}'::jsonb),
    (target_deck_id, 'Albany', 'albany', '''ɔ:bəni', '奥尔巴尼', 'One of my students from Albany, NY was suffering from bouts of severe depression.', '我一个来自纽约奥尔巴尼的学生曾患有严重的抑郁症。', NULL, ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_10']::text[], 10087, '{"originalId":"PEPGaoZhong_10_87"}'::jsonb),
    (target_deck_id, 'Cornwall', 'cornwall', '''kɔ:nwɔ:l', '康沃尔', 'Prince Charles leads an expensive life and the Duchy of Cornwall is there to fund it.', '查尔斯王子过着一种奢侈的生活，这些都由康沃尔公国进行资助。', NULL, ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_10']::text[], 10088, '{"originalId":"PEPGaoZhong_10_88"}'::jsonb),
    (target_deck_id, 'Kent', 'kent', 'kent', 'n. 肯特', 'The most extraordinary safari I ever organised for Abercrombie and Kent was in 1993 when I took Bill and Melinda Gates round East Africa.', '我为阿伯克龙比和肯特组织的最特别的猎游是1993年的时候，当时我带比尔盖茨夫妇去东非。', 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_10']::text[], 10089, '{"originalId":"PEPGaoZhong_10_89"}'::jsonb),
    (target_deck_id, 'burden', 'burden', '''bɝdn', 'n. 负担，担子', 'His family responsibilities had started to become a burden.', '家庭责任已开始成为他的负担。', 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_10']::text[], 10090, '{"originalId":"PEPGaoZhong_10_90"}'::jsonb),
    (target_deck_id, 'hand over', 'hand over', '''hænd,əuvə(r)', '移交（权力、责任）', 'I wouldn''t dare hand this project over to anyone else.', '我可不敢将这个项目交给其他任何人负责。', NULL, ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_10']::text[], 10091, '{"originalId":"PEPGaoZhong_10_91"}'::jsonb),
    (target_deck_id, 'allocate', 'allocate', '''æləket', 'v. 分派，分配', 'Tickets are limited and will be allocated to those who apply first.', '票数有限，将分配给那些先申请的人。', 'v', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_10']::text[], 10094, '{"originalId":"PEPGaoZhong_10_94"}'::jsonb),
    (target_deck_id, 'darling', 'darling', '''dɑrlɪŋ', 'n. 心爱的人
adj. 亲爱的，可爱的', 'Look, darling, there’s Mary.', '看呀，亲爱的，玛丽来了。', 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_10']::text[], 10096, '{"originalId":"PEPGaoZhong_10_96"}'::jsonb),
    (target_deck_id, 'pray', 'pray', 'pre', 'v. 祈祷；恳求，请', 'They went to the mosque to pray.', '他们去清真寺祷告。', 'v', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_10']::text[], 10098, '{"originalId":"PEPGaoZhong_10_98"}'::jsonb),
    (target_deck_id, 'care for', 'care for', NULL, '关怀，照顾', 'She moved back home to care for her elderly parents.', '她搬回家住，好照料年迈的双亲。', NULL, ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_10']::text[], 10099, '{"originalId":"PEPGaoZhong_10_99"}'::jsonb),
    (target_deck_id, 'majesty', 'majesty', '''mædʒəsti', 'n. 最高权威，王权；雄伟', 'The Prime Minister is here to see you, Your Majesty.', '首相前来拜谒，陛下。', 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_10']::text[], 10100, '{"originalId":"PEPGaoZhong_10_100"}'::jsonb),
    (target_deck_id, 'lord', 'lord', 'lɔrd', 'n. 封建领主，地主，统治者；（宗）上帝', 'the feudal lords', '封建领主', 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_10']::text[], 10101, '{"originalId":"PEPGaoZhong_10_101"}'::jsonb),
    (target_deck_id, 'hear out', 'hear out', NULL, '听某人把话说完', 'Perhaps, when you''ve heard me out, you''ll appreciate the reason for secrecy.', '也许当你听我把话讲完后，你就会明白为什么要保密了。', NULL, ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_10']::text[], 10106, '{"originalId":"PEPGaoZhong_10_106"}'::jsonb),
    (target_deck_id, 'flattery', 'flattery', '''flætəri', 'n. 奉承，恭维话', 'He is ambitious and susceptible to flattery.', '他雄心勃勃，而且很喜欢听恭维话。', 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_10']::text[], 10108, '{"originalId":"PEPGaoZhong_10_108"}'::jsonb),
    (target_deck_id, 'flatter', 'flatter', '''flætɚ', 'v. 过分夸赞，奉承，恭维', 'Perry would always flatter Mrs. Mitchell by praising her cooking.', '佩里常常奉承米切尔太太，称赞她的烹调手艺。', 'v', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_10']::text[], 10109, '{"originalId":"PEPGaoZhong_10_109"}'::jsonb),
    (target_deck_id, 'beyond question', 'beyond question', NULL, '无可争辩，毫无疑问', '"As I''m sure you can understand, " she started off with one of the first applicants, "in a business like this, our personal integrity must be beyond question." She leaned forward.', '“我相信您一定能理解，” 她对第一个申请者说，“做我们这种生意的，个人信誉必须是毫无疑问的。”', NULL, ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_10']::text[], 10110, '{"originalId":"PEPGaoZhong_10_110"}'::jsonb),
    (target_deck_id, 'speak out', 'speak out', NULL, '大胆地说，大声地说', 'As tempers rose, he spoke out strongly against some of the radical ideas for selling off state-owned property.', '随着火气上升，他公开表达了对某些卖掉国有资产的过激想法的强烈反对。', NULL, ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_10']::text[], 10111, '{"originalId":"PEPGaoZhong_10_111"}'::jsonb),
    (target_deck_id, 'friction', 'friction', '''frɪkʃən', 'n. 矛盾，冲突；摩擦', 'the usual frictions between parents and their teenage children.', '家长和十几岁的孩子之间常见的摩擦', 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_10']::text[], 10112, '{"originalId":"PEPGaoZhong_10_112"}'::jsonb),
    (target_deck_id, 'pack up', 'pack up', NULL, '把……打包，整理', 'Are you packing up already? It''s only 4 o''clock.', '你已经开始打点行李了？现在才刚刚4点钟。', NULL, ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_10']::text[], 10115, '{"originalId":"PEPGaoZhong_10_115"}'::jsonb),
    (target_deck_id, 'frontier', 'frontier', 'frʌn''tɪr', 'n. 国界，边疆，边境', 'Lille is close to the frontier between France and Belgium.', '里尔靠近法比边境。', 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_10']::text[], 10116, '{"originalId":"PEPGaoZhong_10_116"}'::jsonb),
    (target_deck_id, 'give away', 'give away', NULL, '赠送；泄露', 'He was giving his collection away for free.', '他正在无偿捐赠他的收藏。', NULL, ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_10']::text[], 10117, '{"originalId":"PEPGaoZhong_10_117"}'::jsonb),
    (target_deck_id, 'deceitful', 'deceitful', 'dɪ''sitfl', 'adj. 欺诈的，不诚实的', 'His manner was sly and deceitful.', '他的态度诡诈而又不老实。', 'adj', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_10']::text[], 10120, '{"originalId":"PEPGaoZhong_10_120"}'::jsonb),
    (target_deck_id, 'corrupt', 'corrupt', 'kə''rʌpt', 'adj. 腐败的，贪污的；堕落的', 'Corrupt judges have taken millions of dollars in bribes.', '腐败的法官接受了几百万美元的贿赂。', 'adj', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_10']::text[], 10121, '{"originalId":"PEPGaoZhong_10_121"}'::jsonb),
    (target_deck_id, 'greed', 'greed', 'ɡrid', 'n. 贪婪', 'people motivated by jealousy and greed', '受妒忌和贪婪驱使的人们', 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_10']::text[], 10123, '{"originalId":"PEPGaoZhong_10_123"}'::jsonb),
    (target_deck_id, 'cunning', 'cunning', '''kʌnɪŋ', 'adj. 善于骗人的，狡猾的', 'a cunning opponent', '狡猾的对手', 'adj', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_10']::text[], 10125, '{"originalId":"PEPGaoZhong_10_125"}'::jsonb),
    (target_deck_id, 'strorage', 'strorage', NULL, 'n. 贮藏，存储，储藏室', 'the storage of highly radioactive material', '高放射性材料的存放', 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_10']::text[], 10126, '{"originalId":"PEPGaoZhong_10_126"}'::jsonb),
    (target_deck_id, 'sacrifice', 'sacrifice', '''sækrɪfaɪs', 'n. 牺牲；献身，祭品', 'The minister stressed the need for economic sacrifice.', '部长强调了在经济上作出牺牲的必要性。', 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_10']::text[], 10128, '{"originalId":"PEPGaoZhong_10_128"}'::jsonb),
    (target_deck_id, 'Stratford-on-Avon', 'stratford-on-avon', NULL, '埃文河畔斯特拉特福镇（莎翁故乡）', NULL, NULL, NULL, ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_10']::text[], 10129, '{"originalId":"PEPGaoZhong_10_129"}'::jsonb),
    (target_deck_id, 'Latin', 'latin', '''lætn', 'n. 拉丁文，拉丁语
adj. 拉丁文的，拉丁语的', 'He is well grounded in Latin.', '他拉丁语的功底很扎实。', 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_10']::text[], 10130, '{"originalId":"PEPGaoZhong_10_130"}'::jsonb),
    (target_deck_id, 'make a name', 'make a name', NULL, '出名', 'Focus on those big tasks, that will make a name for you, that will generate long-term income, that will give you lasting satisfaction and happiness.', '把精力放在那些重要任务上，它们将使你成名，带来长时间的回报和长时间的幸福与满足。', NULL, ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_10']::text[], 10131, '{"originalId":"PEPGaoZhong_10_131"}'::jsonb),
    (target_deck_id, 'sneeze', 'sneeze', 'sniz', 'n. 喷嚏
vi. 打喷嚏', 'There was a loud sneeze from someone in the back of the audience.', '后面的观众中有人大声打了个喷嚏。', 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_10']::text[], 10133, '{"originalId":"PEPGaoZhong_10_133"}'::jsonb),
    (target_deck_id, 'rewind', 'rewind', ',ri''waɪnd', 'v. 重绕，倒回', 'Wendy rewound the tape and played the message again.', '温迪把录音带倒了回去，把那条留言又放了一遍。', 'v', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_10']::text[], 10136, '{"originalId":"PEPGaoZhong_10_136"}'::jsonb),
    (target_deck_id, 'cheque', 'cheque', 'tʃɛk', 'n. 支票', 'You could write her a cheque.', '你可以给她开张支票。', 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_10']::text[], 10138, '{"originalId":"PEPGaoZhong_10_138"}'::jsonb),
    (target_deck_id, 'terminal', 'terminal', 'tɝ​mənl', 'n. 终点站，航空集散站', 'the airport’s passenger terminal', '机场航站楼', 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_10']::text[], 10140, '{"originalId":"PEPGaoZhong_10_140"}'::jsonb),
    (target_deck_id, 'vacant', 'vacant', '''vekənt', 'adj. 空的，空缺的', 'Only a few apartments were still vacant.', '只有几套公寓仍然空着。', 'adj', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_10']::text[], 10141, '{"originalId":"PEPGaoZhong_10_141"}'::jsonb),
    (target_deck_id, 'Burgundy', 'burgundy', '''bɝɡəndi', '勃艮第', '...a bottle of white burgundy.', '...一瓶勃艮第白葡萄酒。', NULL, ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_10']::text[], 10143, '{"originalId":"PEPGaoZhong_10_143"}'::jsonb),
    (target_deck_id, 'Oswald', 'oswald', '''ɔzwəld', '奥斯瓦尔德', 'But Oswald stressed that the research looked at the average person, and could not account for everyone.', '不过奥斯瓦德强调研究只是针对普通大众，不见得适用于所有人。', NULL, ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_10']::text[], 10145, '{"originalId":"PEPGaoZhong_10_145"}'::jsonb),
    (target_deck_id, 'Caius', 'caius', NULL, '凯厄斯', 'On June 5, 1976, Needham delivered his last sermon as Master of Caius College. I quote from that sermon.', '1976年6月5日，李约瑟作为剑桥大学凯斯学院的院长进行了他最后一次说教或演讲，下边就是他的讲话的引用。', NULL, ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_10']::text[], 10147, '{"originalId":"PEPGaoZhong_10_147"}'::jsonb),
    (target_deck_id, 'insult', 'insult', 'ɪn''sʌlt', 'n. 侮辱，凌辱', 'She was shouting insults at her boyfriend.', '她正对她的男朋友高声辱骂。', 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_10']::text[], 10149, '{"originalId":"PEPGaoZhong_10_149"}'::jsonb),
    (target_deck_id, 'scold', 'scold', 'skold', 'v. 责骂，斥责', 'Do not scold the puppy, but simply and firmly say ‘no’.', '不要责骂小狗，但要干脆利落地说“不”。', 'v', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_10']::text[], 10150, '{"originalId":"PEPGaoZhong_10_150"}'::jsonb),
