    (target_deck_id, 'Serena', 'serena', NULL, '赛丽娜', 'Her next two films are slated to be Cleopatra and Serena, the story of a frontier woman who, among many other things, tries to kill her stepson.', '朱莉接下来的计划包括《新埃及艳后》和《塞丽娜》两部电影，后一部讲述的是一个女人试图杀死继子的故事。', NULL, ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_10']::text[], 10177, '{"originalId":"PEPGaoZhong_10_177"}'::jsonb),
