    (target_deck_id, 'Atticus', 'atticus', NULL, '阿提斯库', 'Greeks still use some ancient sites, such as the Pnyx and the Theater of Herodes Atticus.', '希腊人仍在使用一些古代的场所，如普尼克斯和希罗德•阿提库剧场。', NULL, ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_10']::text[], 10205, '{"originalId":"PEPGaoZhong_10_205"}'::jsonb),
