    (target_deck_id, 'creed', 'creed', 'krid', 'n. 信条', 'It has never been weaker as a political creed .', '作为一种政治信条，它从来没有像现在这样衰微过。', 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_10']::text[], 10212, '{"originalId":"PEPGaoZhong_10_212"}'::jsonb),
    (target_deck_id, 'brotherhood', 'brotherhood', '''brʌðɚhʊd', 'n. 手足情意；兄弟关系', 'the spirit of brotherhood', '互爱精神', 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_10']::text[], 10213, '{"originalId":"PEPGaoZhong_10_213"}'::jsonb),
    (target_deck_id, 'oasis', 'oasis', 'o''esɪs', 'n. （沙漠中）绿洲；舒适的地方', 'The immaculately tended gardens are an oasis in the midst of Cairo''s urban sprawl.', '那些打理得非常整洁的花园是杂乱扩张的开罗市区中的一片绿洲。', 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_10']::text[], 10214, '{"originalId":"PEPGaoZhong_10_214"}'::jsonb),
