    (target_deck_id, 'symphony', 'symphony', '''sɪmfəni', 'n. 交响乐，交响曲', 'Bruckner’s Fifth Symphony', '布鲁克纳的《第五交响曲》', 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_10']::text[], 10216, '{"originalId":"PEPGaoZhong_10_216"}'::jsonb),
    (target_deck_id, 'Jew', 'jew', 'dʒu:', 'n. 犹太人', 'He was a Jew, just as I was.', '他是一个犹太人，正如我本人一样。', 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_10']::text[], 10217, '{"originalId":"PEPGaoZhong_10_217"}'::jsonb),
    (target_deck_id, 'Gentile', 'gentile', NULL, 'n. 非犹太人，异教徒', 'And there are radical messages being spread by people who would kill every moderate Muslim, Jew, Gentile and agnostic alike.', '有人散布激进言论，要杀死每个温和的穆斯林、犹太人、非犹太人和不可知论者。', 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_10']::text[], 10218, '{"originalId":"PEPGaoZhong_10_218"}'::jsonb)
