    (target_deck_id, 'almighty', 'almighty', 'ɔl''maɪti', 'adj. 全能的，有无限权力的', 'the Almighty/Almighty God/Almighty Father', '全能者/全能的上帝/全能的天父', 'adj', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_10']::text[], 10222, '{"originalId":"PEPGaoZhong_10_222"}'::jsonb),
