    (target_deck_id, 'metaphor', 'metaphor', '''mɛtəfɚ', 'n. 隐喻，暗喻', 'She uses some wonderful images and metaphors in her writing.', '她在作品中用了一些绝妙的比喻和暗喻。', 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_10']::text[], 10224, '{"originalId":"PEPGaoZhong_10_224"}'::jsonb),
