    (target_deck_id, 'dominate', 'dominate', '''dɑmɪnet', 'v. 支配，占优势', 'The industry is dominated by five multinational companies.', '这个行业受五家跨国公司控制。', 'v', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_10']::text[], 10228, '{"originalId":"PEPGaoZhong_10_228"}'::jsonb),
