    (target_deck_id, 'centigrade', 'centigrade', '''sɛntɪɡred', 'n. 摄氏温度', 'The number at the bottom is the recommended water temperature in centigrade.', '底部的数字为建议性摄氏度水温。', 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_10']::text[], 10231, '{"originalId":"PEPGaoZhong_10_231"}'::jsonb),
