    (target_deck_id, 'Auckland', 'auckland', 'ˈɔːklənd', 'n. 奥克兰（新西兰北岛西北岸港口城市）', 'I lived in Auckland, New Zealand, in my own flat with my dog.', '我住在新西兰的奥克兰，我与我的狗住在我自己的公寓里。', 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_11']::text[], 11001, '{"originalId":"PEPGaoZhong_11_1"}'::jsonb),
    (target_deck_id, 'Maori', 'maori', '''mauri', 'n. （新西兰的）毛利人，毛利语；毛利语', 'Maori cannibalism has been stamped out in New Zealand and many (but not all) of the archipelagos to its north.', '而在新西兰和新西兰以北的大部分群岛上，毛利人的食人陋习已被扑灭。', 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_11']::text[], 11002, '{"originalId":"PEPGaoZhong_11_2"}'::jsonb),
    (target_deck_id, 'kiwi', 'kiwi', '''kiwi', 'n. 几维鸟（新西兰产的一种无翼鸟）', NULL, NULL, 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_11']::text[], 11003, '{"originalId":"PEPGaoZhong_11_3"}'::jsonb),
    (target_deck_id, 'Stewart Island', 'stewart island', NULL, '斯图尔特岛（新西兰一岛屿）', 'The Little Blue Penguin and the Stewart Island Shag can also be seen here in their natural environment.', '在这里，还可以看到自然生态环境中的小蓝企鹅和斯图尔特岛鹭鸶。', NULL, ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_11']::text[], 11004, '{"originalId":"PEPGaoZhong_11_4"}'::jsonb),
    (target_deck_id, 'tectonic', 'tectonic', 'tɛk''tɑnɪk', 'adj. 地壳构造上的，起因于地壳运动的', 'tectonic movements', '地壳构造运动', 'adj', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_11']::text[], 11005, '{"originalId":"PEPGaoZhong_11_5"}'::jsonb),
    (target_deck_id, 'geological', 'geological', 'dʒɪə''lɑdʒɪkl', 'adj. 地质学的，地质的', 'With geological maps, books, and atlases you can find out all the proven sites of precious minerals.', '有了地质地图、书籍和地图册，你就可以找到所有已探明的珍贵矿藏的位置。', 'adj', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_11']::text[], 11006, '{"originalId":"PEPGaoZhong_11_6"}'::jsonb),
    (target_deck_id, 'plateau', 'plateau', 'plæ''to', 'n. 高原', 'A broad valley opened up leading to a high, flat plateau of cultivated land.', '一个宽阔的山谷展开，通向一片平坦的高原耕地。', 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_11']::text[], 11008, '{"originalId":"PEPGaoZhong_11_8"}'::jsonb)
