    (target_deck_id, 'warlike', 'warlike', '''wɔrlaɪk', 'adj. 好战的，尚武的，善战的', 'a warlike nation', '好战的民族', 'adj', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_11']::text[], 11020, '{"originalId":"PEPGaoZhong_11_20"}'::jsonb),
    (target_deck_id, 'tribe', 'tribe', 'traɪb', 'n. 部落，部族', 'a tribe of Aborigines known as the Dolphin People', '一个叫“海豚族”的澳大利亚土著部落', 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_11']::text[], 11021, '{"originalId":"PEPGaoZhong_11_21"}'::jsonb),
