    (target_deck_id, 'fence', 'fence', 'fɛns', 'n. 栅栏，篱笆，围墙', 'Villagers say the fence would restrict public access to the hills.', '村民们说栅栏将限制公众进入山区。', 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_11']::text[], 11024, '{"originalId":"PEPGaoZhong_11_24"}'::jsonb),
