    (target_deck_id, 'treaty', 'treaty', '''triti', 'n. 条约，协议，协定', 'Both sides have agreed to sign the treaty .', '双方都同意签署该条约。', 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_11']::text[], 11028, '{"originalId":"PEPGaoZhong_11_28"}'::jsonb),
