    (target_deck_id, 'porter', 'porter', '''pɔrtɚ', 'n. 守门人；行李搬运工', 'Our taxi pulled up at Old Delhi station and a porter sprinted to the door.', '我们的出租车停在老德里车站，一个搬运工疾步跑向车门。', 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_11']::text[], 11040, '{"originalId":"PEPGaoZhong_11_40"}'::jsonb),
