    (target_deck_id, 'brunch', 'brunch', 'brʌntʃ', 'n. 早午餐', 'This morning I went to a restaurant famous for its brunch buffet.', '今天早上我去了一个以自助早午餐而闻名的餐厅。', 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_11']::text[], 11045, '{"originalId":"PEPGaoZhong_11_45"}'::jsonb),
