    (target_deck_id, 'Burma', 'burma', '''bə:mə', 'n. 缅甸', 'Burma borders on India.', '缅甸与印度毗邻。', 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_11']::text[], 11047, '{"originalId":"PEPGaoZhong_11_47"}'::jsonb),
    (target_deck_id, 'Lake Taupo', 'lake taupo', NULL, '陶波湖（新西兰最大湖）', 'Lake Taupo''s shore is covered with pieces of pumice.', '陶波湖岸上布满了一片片的浮石。', NULL, ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_11']::text[], 11048, '{"originalId":"PEPGaoZhong_11_48"}'::jsonb),
    (target_deck_id, 'dairy', 'dairy', '''dɛri', 'n. 牛奶场；乳品公司', 'In my childhood, local dairies bought milk from local farmers.', '在我小时候，本地的乳品公司向当地农场主收购牛奶。', 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_11']::text[], 11049, '{"originalId":"PEPGaoZhong_11_49"}'::jsonb),
