    (target_deck_id, 'every so often', 'every so often', NULL, '偶尔，时常', 'Normally loners, every so often these natives of the deserts from West Africa to India turn into vast, voracious swarms that leave hunger and poverty behind them wherever they go.', '这些来自从西非到印度沙漠的土生昆虫通常并不成群，但是偶尔也会汇集成巨大、贪婪的蝗群，它们所到之处能留下的是饥饿和贫困。', NULL, ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_11']::text[], 11130, '{"originalId":"PEPGaoZhong_11_130"}'::jsonb),
    (target_deck_id, 'peculiar', 'peculiar', 'pɪ''kjulɪɚ', 'adj. 古怪的，奇怪的；特殊的，罕见的', 'There was a peculiar smell in the kitchen.', '厨房里有一股怪味。', 'adj', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_11']::text[], 11131, '{"originalId":"PEPGaoZhong_11_131"}'::jsonb),
    (target_deck_id, 'strategy', 'strategy', '''strætədʒi', 'n. 策略', 'the government’s long-term economic strategy', '政府的长期经济策略', 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_11']::text[], 11132, '{"originalId":"PEPGaoZhong_11_132"}'::jsonb),
    (target_deck_id, 'myth', 'myth', 'mɪθ', 'n. 神话，虚构的理念或者故事', 'a book of Greek myths', '一本关于希腊神话的图书', 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_11']::text[], 11133, '{"originalId":"PEPGaoZhong_11_133"}'::jsonb),
    (target_deck_id, 'harmony', 'harmony', '''hɑrməni', 'n. 和谐，融洽', 'I do believe it is possible for different ethnic groups to live together in harmony.', '我确信不同民族的人民可以融洽相处。', 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_11']::text[], 11134, '{"originalId":"PEPGaoZhong_11_134"}'::jsonb),
    (target_deck_id, 'well-balanced', 'well-balanced', '''wel''bælənst', 'adj. 很平衡的，正常的；意识健全的，明智的', '...a well-balanced diet.', '…一份均衡的饮食。', 'adj', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_11']::text[], 11136, '{"originalId":"PEPGaoZhong_11_136"}'::jsonb)
