    (target_deck_id, 'prescription', 'prescription', 'prɪ''skrɪpʃən', 'n. 药方，处方', 'We are trying to cut the price of prescription drugs .', '我们正努力降低处方药的价格。', 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_11']::text[], 11137, '{"originalId":"PEPGaoZhong_11_137"}'::jsonb),
    (target_deck_id, 'cope', 'cope', 'kop', 'v. （妥善地）处理，对付，应付，克服', 'Sometimes I find it hard to cope.', '有时候我觉得很难应付。', 'v', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_11']::text[], 11138, '{"originalId":"PEPGaoZhong_11_138"}'::jsonb),
    (target_deck_id, 'cope with', 'cope with', NULL, '应付，对付，克服', 'She feared she wouldn’t be able to cope with two new babies.', '她担心自己无法应付两个刚出生的宝宝。', NULL, ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_11']::text[], 11139, '{"originalId":"PEPGaoZhong_11_139"}'::jsonb),
    (target_deck_id, 'let down', 'let down', NULL, '使失望，辜负', 'Don''t worry, Xiao, I won''t let you down.', '不要担心，肖，我不会让你失望的。', NULL, ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_11']::text[], 11140, '{"originalId":"PEPGaoZhong_11_140"}'::jsonb),
    (target_deck_id, 'proportion', 'proportion', 'prə''pɔrʃən', 'n. 比例，比率；均衡', 'The proportion of women in the profession had risen to 17.3%.', '从事那个职业的女性比例已经增长到17.3%。', 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_11']::text[], 11141, '{"originalId":"PEPGaoZhong_11_141"}'::jsonb),
    (target_deck_id, 'fulfil', 'fulfil', 'ful''fil', 'v. 满足，实现，达到', 'Visiting Disneyland has fulfilled a boyhood dream .', '迪士尼乐园之游使童年梦想成真。', 'v', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_11']::text[], 11142, '{"originalId":"PEPGaoZhong_11_142"}'::jsonb),
    (target_deck_id, 'agenda', 'agenda', 'ə''dʒɛndə', 'n. 议程（表）', 'The next item on the agenda is the publicity budget.', '议程表上的下一项是宣传预算。', 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_11']::text[], 11144, '{"originalId":"PEPGaoZhong_11_144"}'::jsonb),
    (target_deck_id, 'interval', 'interval', '''ɪntɚvl', 'n. 间隔，间歇；幕间（工间）休息', 'He left the room, returning after a short interval with a message.', '他离开房间，过了一会儿就带回来一条消息。', 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_11']::text[], 11145, '{"originalId":"PEPGaoZhong_11_145"}'::jsonb),
    (target_deck_id, 'session', 'session', '''sɛʃən', 'n. 一段（活动的）事件', 'a training session for teachers about computers', '给教师上的一节电脑培训课', 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_11']::text[], 11146, '{"originalId":"PEPGaoZhong_11_146"}'::jsonb),
    (target_deck_id, 'curriculum', 'curriculum', 'kə''rɪkjələm', 'n. 课程', 'Languages are an essential part of the school curriculum.', '语言是学校课程中必不可少的部分。', 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_11']::text[], 11149, '{"originalId":"PEPGaoZhong_11_149"}'::jsonb),
    (target_deck_id, 'rigid', 'rigid', '''rɪdʒɪd', 'adj. 刻板的，严格的；僵硬的', 'rigid and authoritarian methods of education', '死板、专断的教育方法', 'adj', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_11']::text[], 11152, '{"originalId":"PEPGaoZhong_11_152"}'::jsonb),
    (target_deck_id, 'post-graduate', 'post-graduate', NULL, 'n. 研究生
adj. 研究生的', 'Dr Hoffman did his postgraduate work at Leicester University.', '霍夫曼博士是在莱斯特大学读的研究生。', 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_11']::text[], 11154, '{"originalId":"PEPGaoZhong_11_154"}'::jsonb),
    (target_deck_id, 'stead', 'stead', 'stɛd', 'n. 代替；用处，好处', 'My grandmother and aunt will be there in my parents'' stead.', '我的祖母和姑妈将代替我的父母出席。', 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_11']::text[], 11156, '{"originalId":"PEPGaoZhong_11_156"}'::jsonb),
    (target_deck_id, 'stand sb in good stead', 'stand sb in good stead', NULL, '对某人很有用', 'These two games here will stand them in good stead for the future.', '这里的两场比赛对他们的将来很有用。', NULL, ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_11']::text[], 11157, '{"originalId":"PEPGaoZhong_11_157"}'::jsonb),
    (target_deck_id, 'employer', 'employer', 'ɪm''plɔɪɚ', 'n. 雇主，老板', 'The shoe factory is the largest employer in this area.', '这家制鞋厂是本地区最大的雇主。', 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_11']::text[], 11158, '{"originalId":"PEPGaoZhong_11_158"}'::jsonb),
    (target_deck_id, 'format', 'format', '''fɔrmæt', 'n. 设计，安排', 'The courses were run to a consistent format.', '这些课程的编排是有连续性的。', 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_11']::text[], 11160, '{"originalId":"PEPGaoZhong_11_160"}'::jsonb),
    (target_deck_id, 'glory in', 'glory in', NULL, '以……为荣', 'She didn’t like to glory in her past victories.', '她不喜欢躺在过去的功劳簿上不思进取。', NULL, ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_11']::text[], 11162, '{"originalId":"PEPGaoZhong_11_162"}'::jsonb),
    (target_deck_id, 'forgetful', 'forgetful', 'fɚ''gɛtfəl', 'adj. 健忘的', 'My mother has become very forgetful and confused.', '我母亲已变得很健忘很糊涂了。', 'adj', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_11']::text[], 11163, '{"originalId":"PEPGaoZhong_11_163"}'::jsonb),
    (target_deck_id, 'choir', 'choir', '''kwaɪɚ', 'n. 合唱团', 'He joined a church choir at the age of eight.', '他八岁时加入了一个教堂唱诗班。', 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_11']::text[], 11165, '{"originalId":"PEPGaoZhong_11_165"}'::jsonb),
    (target_deck_id, 'withdraw', 'withdraw', 'wɪð''drɔ', 'v. 收回，撤回；变得沉默寡言，冷漠，冷淡', 'After much persuasion he agreed to withdraw his resignation.', '几经劝说，他同意收回辞呈。', 'v', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_11']::text[], 11167, '{"originalId":"PEPGaoZhong_11_167"}'::jsonb),
    (target_deck_id, 'sake', 'sake', 'sek', 'n. 目的，利益', 'After all, we are doing this for the sake of Singaporeans.', '其实，这项政策也是以新加坡人的利益为出发点。', 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_11']::text[], 11168, '{"originalId":"PEPGaoZhong_11_168"}'::jsonb),
    (target_deck_id, 'for one’s own sake', 'for one’s own sake', NULL, '为了……的缘故', 'I hope he’s told the truth for his own sake (= because it will be good for him ) .', '为了他自己好，我希望他已经说出了真相。', NULL, ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_11']::text[], 11169, '{"originalId":"PEPGaoZhong_11_169"}'::jsonb),
    (target_deck_id, 'pursuit', 'pursuit', 'pɚ''sut', 'n. 寻求，追求', 'People are having to move to other areas in pursuit of work.', '为了找工作，人们不得不移居他处。', 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_11']::text[], 11170, '{"originalId":"PEPGaoZhong_11_170"}'::jsonb),
    (target_deck_id, 'pursue', 'pursue', 'pə''sʊ', 'v. 追求，寻求不断努力以取得', 'She plans to pursue a career in politics.', '她计划从政。', 'v', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_11']::text[], 11171, '{"originalId":"PEPGaoZhong_11_171"}'::jsonb),
    (target_deck_id, 'pedicab', 'pedicab', '''pɛdɪ,kæb', 'n. （人力）三轮车', 'Even pedicab drivers were carrying tea samples and looking for clients on the street.', '他说，“甚至连三轮车夫都带着茶样，满街寻找顾客。”', 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_11']::text[], 11172, '{"originalId":"PEPGaoZhong_11_172"}'::jsonb),
    (target_deck_id, 'sleep rough', 'sleep rough', NULL, '露宿', 'Centrepoint said the number of people under the age of 25 forced to sleep rough in London had more than doubled since 2011.', '中心点称25岁以下的人数被迫露宿在伦敦，自2011年以来已经翻了一倍多。', NULL, ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_11']::text[], 11173, '{"originalId":"PEPGaoZhong_11_173"}'::jsonb),
    (target_deck_id, 'feed on', 'feed on', NULL, '从……中得到滋养或者满足', 'Racism feeds on fear.', '恐惧心理会助长种族主义。', NULL, ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_11']::text[], 11174, '{"originalId":"PEPGaoZhong_11_174"}'::jsonb),
    (target_deck_id, 'philosophical', 'philosophical', ',fɪlə''sɑfɪkl', 'adj. 哲学上的', 'the philosophical problem of whether there is free will', '关于是否有自由意志的哲学问题', 'adj', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_11']::text[], 11175, '{"originalId":"PEPGaoZhong_11_175"}'::jsonb),
    (target_deck_id, 'receipt', 'receipt', 'rɪ''sit', 'n. 收据，收条', 'Keep your receipt in case you want to bring it back.', '保留收据以备退货之需。', 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_11']::text[], 11177, '{"originalId":"PEPGaoZhong_11_177"}'::jsonb),
    (target_deck_id, 'outweigh', 'outweigh', '''aʊt''we', 'v. 比……更重要，胜过', 'The benefits of the scheme outweigh the disadvantages.', '这项计划利大于弊。', 'v', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_11']::text[], 11178, '{"originalId":"PEPGaoZhong_11_178"}'::jsonb),
    (target_deck_id, 'ensure', 'ensure', 'ɪn''ʃʊr', 'v. 确保，保证', 'facilities to ensure the safety of cyclists', '确保骑车人安全的设施', 'v', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_11']::text[], 11179, '{"originalId":"PEPGaoZhong_11_179"}'::jsonb),
    (target_deck_id, 'reproach', 'reproach', 'rɪ''protʃ', 'n. 责骂，责备', '‘You don’t need me,’ she said quietly, without reproach.', '“你不需要我。”她语气平静，没有丝毫责备。', 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_11']::text[], 11180, '{"originalId":"PEPGaoZhong_11_180"}'::jsonb),
    (target_deck_id, 'jealousy', 'jealousy', '''dʒɛləsi', 'n. 嫉妒，羡慕', 'Sexual jealousy is a common motive for murder.', '性嫉妒是常见的谋杀动机。', 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_11']::text[], 11181, '{"originalId":"PEPGaoZhong_11_181"}'::jsonb),
    (target_deck_id, 'cease', 'cease', 'sis', 'v. 结束，停息，终止', 'The things people will do for charity never cease to amaze me (= I am always surprised by them ) .', '人们的慈善义举总是让我感到惊讶。', 'v', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_11']::text[], 11182, '{"originalId":"PEPGaoZhong_11_182"}'::jsonb),
    (target_deck_id, 'cease to be', 'cease to be', NULL, '不再是', 'This would deny its own totalitarian nature and it would cease to be itself.', '这样，就否认了它的极权性质，而它也将不再是那个极权的自己。', NULL, ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_11']::text[], 11183, '{"originalId":"PEPGaoZhong_11_183"}'::jsonb),
    (target_deck_id, 'count up', 'count up', NULL, '把……加起来', NULL, NULL, NULL, ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_11']::text[], 11184, '{"originalId":"PEPGaoZhong_11_184"}'::jsonb),
    (target_deck_id, 'reinforce', 'reinforce', ',riɪn''fɔrs', 'v. 增强，补充', 'The film reinforces the idea that women should be pretty and dumb.', '这部影片强化了这个观点——女人要漂亮，而且要笨一些。', 'v', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_11']::text[], 11185, '{"originalId":"PEPGaoZhong_11_185"}'::jsonb),
    (target_deck_id, 'Odysseus', 'odysseus', 'əu''disju:s', '奥德修斯', 'In order to steal it out, Odysseus and Diomedes slipped into the capital one night in  disguise , known to none but Hellen.', '为了将神像偷出城, 一天夜里奥德修斯和狄俄墨德斯乔装改扮潜入首都, 这一切只有海伦知道。', NULL, ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_11']::text[], 11186, '{"originalId":"PEPGaoZhong_11_186"}'::jsonb),
    (target_deck_id, 'Trojan', 'trojan', NULL, 'adj. （古代小亚细亚）特洛伊（Troy）的', NULL, NULL, 'adj', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_11']::text[], 11187, '{"originalId":"PEPGaoZhong_11_187"}'::jsonb),
    (target_deck_id, 'Ithaca', 'ithaca', '''iθəkə', 'n. 伊萨卡岛（希腊西部爱奥尼海中亚群岛之一）', 'Oxford and Cambridge (England) feel like Ithaca or Hanover: the message is there, but not as strong.', '英国的牛津和剑桥感觉就像伊萨卡岛或者汉诺威：虽然也在发着类似的消息，但是比较微弱。', 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_11']::text[], 11188, '{"originalId":"PEPGaoZhong_11_188"}'::jsonb),
    (target_deck_id, 'Telemachus', 'telemachus', 'ti''leməkəs; tə-', '忒勒玛科斯（Odysseus 和 Penelope 之子）', 'Telemachus, in Homer’s story of the Odyssey, tipped his vehicle vertically against a wall, while others removed their wheels in the evening (Gordon, 1978) to prevent warping.', '荷马史诗里的忒勒马科斯在晚上把他的车竖直靠墙，而其他的车则被卸去了轮毂以防止变形（戈登，1978）。', NULL, ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_11']::text[], 11189, '{"originalId":"PEPGaoZhong_11_189"}'::jsonb),
    (target_deck_id, 'split', 'split', 'splɪt', 'v. 分开，分离', 'It was feared that the issue would split the church.', '人们担心这一问题会导致教会分裂。', 'v', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_11']::text[], 11190, '{"originalId":"PEPGaoZhong_11_190"}'::jsonb),
    (target_deck_id, 'violate', 'violate', '''vaɪəlet', 'v. 违犯，违反', '34 protesters were arrested for violating criminal law.', '34名抗议者因违反刑法而被逮捕。', 'v', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_11']::text[], 11191, '{"originalId":"PEPGaoZhong_11_191"}'::jsonb),
    (target_deck_id, 'Penelope', 'penelope', 'pə''nɛləpi', '珀涅罗珀（Odysseus 的忠实妻子）', NULL, NULL, NULL, ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_11']::text[], 11193, '{"originalId":"PEPGaoZhong_11_193"}'::jsonb),
    (target_deck_id, 'statesman', 'statesman', '''stetsmən', 'n. 政治家，国务活动家', 'a respected elder statesman', '一位受人尊敬的政界元老', 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_11']::text[], 11194, '{"originalId":"PEPGaoZhong_11_194"}'::jsonb),
    (target_deck_id, 'statesmanlike', 'statesmanlike', '''stetsmən''laɪk', 'adj. 有政治家才干和风度的', 'his statesmanlike handling of the crisis', '他处理这场危机时表现出的政治家才干', 'adj', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_11']::text[], 11195, '{"originalId":"PEPGaoZhong_11_195"}'::jsonb),
    (target_deck_id, 'unconditional', 'unconditional', ',ʌnkən''dɪʃənl', 'adj. 无条件的，无限制的,绝对的', 'the unconditional release of all political prisoners', '所有政治犯的无条件释放', 'adj', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_11']::text[], 11196, '{"originalId":"PEPGaoZhong_11_196"}'::jsonb),
    (target_deck_id, 'Cyclops', 'cyclops', '''saɪklɑps', '塞克罗伯斯（希腊神话独眼巨人）', NULL, NULL, NULL, ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_11']::text[], 11197, '{"originalId":"PEPGaoZhong_11_197"}'::jsonb),
    (target_deck_id, 'scar', 'scar', 'skɑr', 'n. 疤，伤疤；创伤', 'He had a long, curved scar on his right cheek.', '他的右脸上有一道弯弯的长疤。', 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_11']::text[], 11198, '{"originalId":"PEPGaoZhong_11_198"}'::jsonb),
    (target_deck_id, 'at the crack of dawn', 'at the crack of dawn', NULL, '黎明，大清早', 'We were up at the crack of dawn.', '我们一大清早就起来了。', NULL, ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_11']::text[], 11201, '{"originalId":"PEPGaoZhong_11_201"}'::jsonb),
    (target_deck_id, 'quick as a flash', 'quick as a flash', NULL, '立刻，马上，一刹那', 'Quick as a flash she was at his side.', '她旋即来到他身边。', NULL, ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_11']::text[], 11202, '{"originalId":"PEPGaoZhong_11_202"}'::jsonb),
    (target_deck_id, 'heel', 'heel', 'hil', 'n. 脚后跟，踵', 'He had an operation on his heel last week.', '他上星期脚后跟做了手术。', 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_11']::text[], 11205, '{"originalId":"PEPGaoZhong_11_205"}'::jsonb),
    (target_deck_id, 'a wolf in sheep’s clothing', 'a wolf in sheep’s clothing', NULL, '披着羊皮的狼，伪装好友的敌人', NULL, NULL, NULL, ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_11']::text[], 11206, '{"originalId":"PEPGaoZhong_11_206"}'::jsonb),
    (target_deck_id, 'pint', 'pint', 'paɪnt', 'n. 品脱（等于05 夸脱，英制液量 0568 升，美制液量 0473 升）', 'Add two pints of water to the mixture.', '在混合物中加入两品脱的水。', 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_11']::text[], 11207, '{"originalId":"PEPGaoZhong_11_207"}'::jsonb),
    (target_deck_id, 'dead to the world', 'dead to the world', NULL, '熟睡的', NULL, NULL, NULL, ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_11']::text[], 11208, '{"originalId":"PEPGaoZhong_11_208"}'::jsonb),
    (target_deck_id, 'socket', 'socket', '''sɑkɪt', 'n. 孔，洞；眼窝', 'a headphone socket', '耳机插口', 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_11']::text[], 11209, '{"originalId":"PEPGaoZhong_11_209"}'::jsonb),
    (target_deck_id, 'stagger', 'stagger', '''stægɚ', 'n. 蹒跚，摇晃，踉跄', 'to walk with a stagger', '蹒跚着走', 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_11']::text[], 11210, '{"originalId":"PEPGaoZhong_11_210"}'::jsonb),
    (target_deck_id, 'agony', 'agony', '''æɡəni', 'n. 极度的痛苦', 'During that year of agony and the following year of my grieving, everything stopped for me.', '在那一年的痛苦和接下来整整一年的悲恸中，我生活中的一切都停止了。', 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_11']::text[], 11211, '{"originalId":"PEPGaoZhong_11_211"}'::jsonb),
    (target_deck_id, 'belly', 'belly', '''bɛli', 'n. 腹部', 'She laid her hands on her swollen belly.', '她把手放在隆起的肚子上。', 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_11']::text[], 11212, '{"originalId":"PEPGaoZhong_11_212"}'::jsonb),
    (target_deck_id, 'wrestle', 'wrestle', '''rɛsl', 'v. 与……搏斗，把……摔倒', 'They taught me to wrestle.', '他们教我去摔跤。', 'v', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_11']::text[], 11213, '{"originalId":"PEPGaoZhong_11_213"}'::jsonb),
    (target_deck_id, 'Circe', 'circe', '''sə:si', '瑟茜（希腊神话女巫，有把人变成猪的法术）', 'Cookery means the knowledge of Medea and of Circe and of Helen and of the Queen of Sheba.', '烹饪术包含着美狄娅、瑟西、海伦和希巴女王的学问。', NULL, ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_11']::text[], 11214, '{"originalId":"PEPGaoZhong_11_214"}'::jsonb),
    (target_deck_id, 'arch', 'arch', 'ɑrtʃ', 'n. 拱门', 'Looking from a distance like a gigantic arch, it is a continuous loop, a kind of square doughnut.', '从远处看像一座巨大的拱门，实际上它是一个连续的环，有点像方形面包圈。', 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_11']::text[], 11216, '{"originalId":"PEPGaoZhong_11_216"}'::jsonb),
    (target_deck_id, 'coarse', 'coarse', 'kɔrs', 'adj. 粗糙的；鲁莽的', 'a jacket of coarse wool', '粗羊毛夹克衫', 'adj', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_11']::text[], 11217, '{"originalId":"PEPGaoZhong_11_217"}'::jsonb),
    (target_deck_id, 'trough', 'trough', 'trɔf', 'n. 饲料槽', 'The old stone cattle trough still sits by the main entrance.', '那尊古老的石制牛食槽依旧位于主要入口处。', 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_11']::text[], 11220, '{"originalId":"PEPGaoZhong_11_220"}'::jsonb),
    (target_deck_id, 'slice', 'slice', NULL, 'n. 片，薄片', 'Cut the tomatoes into slices.', '把番茄切成片。', 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_11']::text[], 11221, '{"originalId":"PEPGaoZhong_11_221"}'::jsonb),
    (target_deck_id, 'wear off', 'wear off', NULL, '逐渐消失，磨灭，损耗', 'For many the philosophy was merely a fashion, and the novelty soon wore off.', '对很多人而言这种哲学只是一时时髦，新鲜感很快就消失了。', NULL, ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_11']::text[], 11222, '{"originalId":"PEPGaoZhong_11_222"}'::jsonb),
    (target_deck_id, 'saucer', 'saucer', '''sɔsɚ', 'n. 茶托，茶杯碟，碟状物', 'a china cup and saucer', '一套瓷茶杯和杯托', 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_11']::text[], 11223, '{"originalId":"PEPGaoZhong_11_223"}'::jsonb),
    (target_deck_id, 'circus', 'circus', '''sɝkəs', 'n. 马戏团，马戏表演', 'My real ambition was to work in a circus.', '我真正的理想是去马戏团工作。', 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_11']::text[], 11224, '{"originalId":"PEPGaoZhong_11_224"}'::jsonb),
    (target_deck_id, 'plug', 'plug', 'plʌɡ', 'n. 电插头，插销', 'The plug on my iron needs changing.', '我熨斗上的插头需要更换了。', 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_11']::text[], 11226, '{"originalId":"PEPGaoZhong_11_226"}'::jsonb),
    (target_deck_id, 'hydrogen', 'hydrogen', '''haɪdrədʒən', 'n. 氢', 'Water can be reduced to oxygen and hydrogen by electrolysis.', '水通过电解可以分解为氧和氢。', 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_11']::text[], 11227, '{"originalId":"PEPGaoZhong_11_227"}'::jsonb),
    (target_deck_id, 'mustard', 'mustard', '''mʌstɚd', 'n. 芥末', 'I''m not especially fond of mustard.', '芥末我吃不来。', 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_11']::text[], 11230, '{"originalId":"PEPGaoZhong_11_230"}'::jsonb),
    (target_deck_id, 'Theseus', 'theseus', '''θi:sju:s; -siəs', '忒修斯（希腊神话雅典王子）', 'Nietzsche often spoke of Ariadne, a faithful companion of Theseus.', '尼采经常提到阿里阿德涅，她是提修斯忠实的伴侣。', NULL, ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_11']::text[], 11231, '{"originalId":"PEPGaoZhong_11_231"}'::jsonb),
    (target_deck_id, 'enlarge', 'enlarge', 'ɪn''lɑrdʒ', 'v. 增大，扩大', 'an operation to enlarge her breasts', '她的丰胸手术', 'v', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_11']::text[], 11232, '{"originalId":"PEPGaoZhong_11_232"}'::jsonb),
    (target_deck_id, 'combat', 'combat', '''kɑmbæt', 'n. 战争，战斗，斗争', 'We flew over 200 combat missions in the war.', '我们在战争中执行过两百多次战斗飞行任务。', 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_11']::text[], 11235, '{"originalId":"PEPGaoZhong_11_235"}'::jsonb),
    (target_deck_id, 'transparent', 'transparent', 'træns''pærənt', 'adj. 透明的，显然的，一目了然的', 'a transparent plastic container', '透明的塑料容器', 'adj', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_11']::text[], 11237, '{"originalId":"PEPGaoZhong_11_237"}'::jsonb),
    (target_deck_id, 'transparently', 'transparently', NULL, 'adv. 显然地，清楚地', 'transparently obvious', '显而易见', 'adv', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_11']::text[], 11238, '{"originalId":"PEPGaoZhong_11_238"}'::jsonb),
    (target_deck_id, 'tug', 'tug', 'tʌɡ', 'v. 用力拉或拖（某物）', 'The woman gently tugged his arm.', '那女人轻轻拽了拽他的胳膊。', 'v', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_11']::text[], 11239, '{"originalId":"PEPGaoZhong_11_239"}'::jsonb),
    (target_deck_id, 'dismay', 'dismay', 'dɪs''me', 'v. 使沮丧，使灰心', 'The poor election turnout dismayed politicians.', '投票人数少，政治家们感到失望。', 'v', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_11']::text[], 11240, '{"originalId":"PEPGaoZhong_11_240"}'::jsonb),
    (target_deck_id, 'zoom', 'zoom', 'zum', 'v. 飞驰，飞快地掠过', 'Brenda jumped in the car and zoomed off.', '布伦达跳上汽车，疾驰而去。', 'v', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_11']::text[], 11242, '{"originalId":"PEPGaoZhong_11_242"}'::jsonb),
    (target_deck_id, 'zoom in on', 'zoom in on', NULL, '推近，聚焦于', 'The camera zoomed in on the actor''s face.', '摄影机将演员的脸拉近了。', NULL, ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_11']::text[], 11243, '{"originalId":"PEPGaoZhong_11_243"}'::jsonb),
    (target_deck_id, 'insignificant', 'insignificant', ',ɪnsɪɡ''nɪfɪkənt', 'adj. 无关紧要的', 'In 1949 Bonn was a small, insignificant city.', '1949年，波恩还是个不足称道的小城市。', 'adj', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_11']::text[], 11244, '{"originalId":"PEPGaoZhong_11_244"}'::jsonb),
    (target_deck_id, 'Sinis', 'sinis', NULL, '西尼斯（古希腊神话中的一个强盗）', 'Sinis caught sight of Theseus and hailed him.', '辛尼斯看到忒修思，就和 他打招呼。', NULL, ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_11']::text[], 11245, '{"originalId":"PEPGaoZhong_11_245"}'::jsonb),
    (target_deck_id, 'Procrustes', 'procrustes', 'prəu''krʌsti:z', '普罗克拉斯提斯（古希腊神话传说中 Attica 的一个强盗）', 'Near to the banks of the Cephissus lived the giant Procrustes , of whom (as was the case with other giants) Theseus had heard long before he met him.', '在科菲索斯河岸边住着巨人普洛克洛斯忒斯，就象其它的巨人一样，忒修斯早就听说了他的情况。', NULL, ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_11']::text[], 11246, '{"originalId":"PEPGaoZhong_11_246"}'::jsonb),
    (target_deck_id, 'Crete', 'crete', 'kri:t', '克里特岛（希腊位于地中海西部的一个岛屿）', 'Pavlos Tsimas says some people commit suicide in a public way, like the businessman in Crete.', '特斯马斯表示一些人以公开的方式自杀，就像克里特岛这位小商人。', NULL, ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_11']::text[], 11247, '{"originalId":"PEPGaoZhong_11_247"}'::jsonb),
    (target_deck_id, 'fleece', 'fleece', 'flis', 'n. 羊毛', '...a special protein which triggers the animal to shed its fleece.', '…一种能够促使这种动物脱毛的特殊蛋白质。', 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_11']::text[], 11248, '{"originalId":"PEPGaoZhong_11_248"}'::jsonb),
    (target_deck_id, 'Perseus', 'perseus', '''pə:sju:s; -siəs', '珀尔休斯（希腊主神宙斯之女，杀死怪 Medusa 的英雄）', 'The hero is Perseus, called a demi-god, because his father is Zeus the god, while his mother a human.', '我们的主角是珀尔修斯，他是一个半人神，因为他的爸爸是一个神，宙斯，而他的妈妈是一个人。', NULL, ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_11']::text[], 11249, '{"originalId":"PEPGaoZhong_11_249"}'::jsonb),
    (target_deck_id, 'vice versa', 'vice versa', ',vaisi''və:sə', '反之亦然', 'The boys may refuse to play with the girls, and vice versa.', '男孩可能拒绝和女孩玩耍，反之亦然。', NULL, ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_11']::text[], 11250, '{"originalId":"PEPGaoZhong_11_250"}'::jsonb),
    (target_deck_id, '(be) faced with', '(be) faced with', NULL, '面临', NULL, NULL, NULL, ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_11']::text[], 11251, '{"originalId":"PEPGaoZhong_11_251"}'::jsonb),
    (target_deck_id, 'in disbelief', 'in disbelief', NULL, '不相信，怀疑', 'Rosie stared in disbelief.', '罗茜疑惑地瞪大了眼睛。', NULL, ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_11']::text[], 11253, '{"originalId":"PEPGaoZhong_11_253"}'::jsonb),
    (target_deck_id, 'drop into', 'drop into', NULL, '进入（某地），顺便拜访', 'I thought I''d drop in on you while I was passing.', '我曾想路过时顺便来看看你。', NULL, ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_11']::text[], 11254, '{"originalId":"PEPGaoZhong_11_254"}'::jsonb),
    (target_deck_id, 'unsettling', 'unsettling', 'ʌn''sɛtlɪŋ', 'adj. 使人不安的，（消息）混乱的', 'Phil had several unsettling dreams every night.', '菲尔每晚都做好几个令他不安的梦。', 'adj', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_11']::text[], 11255, '{"originalId":"PEPGaoZhong_11_255"}'::jsonb),
    (target_deck_id, 'dozens of', 'dozens of', NULL, '许多的', 'As a result, like the physicians in my study, we make dozens of small, subtle and almost invisible choices about how to spend our time.', '所以这结果就变得和我研究组里的医生们一样：做了许许多多琐碎的微不足道的选择和权衡，来安排我们的时间。', NULL, ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_11']::text[], 11256, '{"originalId":"PEPGaoZhong_11_256"}'::jsonb),
    (target_deck_id, 'now and again', 'now and again', NULL, '不时地，有时', 'There were mainly foreigners living there, so we could chat with them now and again.', '那里进进出出都是外国人, 我们可以时不时和他们搭讪聊天.', NULL, ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_11']::text[], 11257, '{"originalId":"PEPGaoZhong_11_257"}'::jsonb),
    (target_deck_id, 'expectantly', 'expectantly', NULL, 'adv. 预期地，期望地，期待地', 'She looked at him expectantly.', '她满怀期望地看着他。', 'adv', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_11']::text[], 11258, '{"originalId":"PEPGaoZhong_11_258"}'::jsonb),
    (target_deck_id, 'co-operate', 'co-operate', 'kəu''ɔpəreit', 'v. （常与 with 连用）合作', 'The U.N. had been cooperating with the State Department on a plan to find countries willing to take the refugees.', '联合国和美国国务院合作，制定计划来寻找愿意接纳难民的国家。', 'v', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_11']::text[], 11260, '{"originalId":"PEPGaoZhong_11_260"}'::jsonb),
    (target_deck_id, 'hand out', 'hand out', NULL, '拿出，分发', 'One of my jobs was to hand out the prizes.', '我的工作之一是分发奖品。', NULL, ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_11']::text[], 11261, '{"originalId":"PEPGaoZhong_11_261"}'::jsonb),
    (target_deck_id, 'pleasureable', 'pleasureable', NULL, 'adj. 愉快的，快乐的，高兴的', 'a pleasurable experience', '愉快的经历', 'adj', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_11']::text[], 11263, '{"originalId":"PEPGaoZhong_11_263"}'::jsonb),
    (target_deck_id, 'anticipation', 'anticipation', 'æn,tɪsɪ''peʃən', 'n. 预期，预想，期待', 'She waited in eager anticipation for Robert to arrive.', '她急切地期盼着罗伯特到来。', 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_11']::text[], 11264, '{"originalId":"PEPGaoZhong_11_264"}'::jsonb),
    (target_deck_id, 'intellectual', 'intellectual', ',ɪntə''lɛktʃuəl', 'adj. 有智力的，智力的', 'Mark’s very intellectual.', '马克很聪明。', 'adj', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_11']::text[], 11265, '{"originalId":"PEPGaoZhong_11_265"}'::jsonb),
    (target_deck_id, 'arithmetic', 'arithmetic', 'ə''rɪθmətɪk', 'n. 算术学，算术', '...teaching the basics of reading, writing and arithmetic.', '…教授读、写、算的基本知识。', 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_11']::text[], 11266, '{"originalId":"PEPGaoZhong_11_266"}'::jsonb)
  ON CONFLICT (deck_id, normalized_word) DO NOTHING;

