    deck_id, word, normalized_word, phonetic, meaning, example, example_translation, part_of_speech, tags, sort_index, metadata
  ) VALUES
    (target_deck_id, 'algebra', 'algebra', '''ældʒɪbrə', 'n. 代数，代数学', 'My  behavior is on  behalf of half  zebras," the  algebra teacher said.', '"我的行为代表了一半斑马的利益,"代数老师说.', 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_11']::text[], 11267, '{"originalId":"PEPGaoZhong_11_267"}'::jsonb),
    (target_deck_id, 'interpersonal', 'interpersonal', '''ɪntɚ''pɝsnl', 'adj. 人际的，人与人之间的', 'interpersonal skills', '人际交往技巧', 'adj', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_11']::text[], 11268, '{"originalId":"PEPGaoZhong_11_268"}'::jsonb),
    (target_deck_id, 'agro-scientifc', 'agro-scientifc', NULL, 'adj. 农业科学的', NULL, NULL, 'adj', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_11']::text[], 11270, '{"originalId":"PEPGaoZhong_11_270"}'::jsonb),
    (target_deck_id, 'core', 'core', 'kɔr', 'n. 中心，核心', 'The core of the book focuses on the period between 1660 and 1857.', '这本书的中心内容集中在1660年到1857年这段时期。', 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_11']::text[], 11271, '{"originalId":"PEPGaoZhong_11_271"}'::jsonb),
    (target_deck_id, 'drop in', 'drop in', NULL, '顺便走访', 'Why not drop in for a chat?', '为何不顺道过来聊聊？', NULL, ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_11']::text[], 11272, '{"originalId":"PEPGaoZhong_11_272"}'::jsonb),
    (target_deck_id, 'recommendation', 'recommendation', ',rɛkəmɛn''deʃən', 'n. 推荐信，介绍，介绍信', 'Try to get letters of recommendation from bosses and colleagues.', '设法得到老板和同事的推荐信。', 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_11']::text[], 11273, '{"originalId":"PEPGaoZhong_11_273"}'::jsonb),
    (target_deck_id, 'call on', 'call on', NULL, '拜访', 'Sofia was intending to call on Miss Kitts.', '索菲娅打算去拜访基茨小姐。', NULL, ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_11']::text[], 11274, '{"originalId":"PEPGaoZhong_11_274"}'::jsonb),
    (target_deck_id, 'composer', 'composer', 'kəm''pozɚ', 'n. 作曲家', '...music by Strauss, Mozart, Beethoven, and other great composers.', '…施特劳斯、莫扎特、贝多芬及其他伟大作曲家创作的音乐。', 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_11']::text[], 11275, '{"originalId":"PEPGaoZhong_11_275"}'::jsonb),
    (target_deck_id, 'mathematician', 'mathematician', ',mæθəmə''tɪʃən', 'n. 数学家', 'The risks can be so complex that banks hire mathematicians to assess them.', '这类风险可以是如此复杂以至于银行雇佣数学家们去评估它们。', 'n', ARRAY['PEP', 'GaoZhong', 'PEPGaoZhong_11']::text[], 11276, '{"originalId":"PEPGaoZhong_11_276"}'::jsonb),
